def messages(case):
    return [{"role": "system", "content": PROMPT if case["kind"] == "translation" else SYSTEM},
            {"role": "user", "content": compact_json(case["payload"])}]

def assess(case, output):
    if not isinstance(output, dict):
        return {"json_object": False}
    if case["kind"] == "extraction":
        return {"exact_field_set": set(output) == set(case["expected"]),
                **{key: type(output.get(key)) is type(value) and output.get(key) == value
                   for key, value in case["expected"].items()}}
    translated = output.get("translations")
    if not isinstance(translated, dict):
        return {"translation_map": False}
    checks = {"exact_field_set": set(output) == {"translations"},
              "all_keys": set(translated) == set(case["payload"])}
    for key, source in case["payload"].items():
        target = translated.get(key)
        checks[key + "_english"] = isinstance(target, str) and bool(target.strip()) and not re.search(r"[\u3400-\u9fff]", target)
        checks[key + "_numbers"] = isinstance(target, str) and Counter(re.findall(r"\d+", target)) == Counter(re.findall(r"\d+", source))
    patterns = {
        "age_guardian_boundary": ("text_0", r"guardian", r"(?:not|no|without)", r"(?:under|below|younger)"),
        "fee_exception": ("text_1", r"(?:only|solely)", r"(?:first|initial)", r"(?:expir|renew)"),
        "working_calendar_negation": ("text_2", r"working|business", r"calendar", r"not|no|mustn't|cannot")}
    for key, (slot, *terms) in patterns.items():
        target = translated.get(slot, "")
        checks[key] = isinstance(target, str) and all(re.search(term, target, re.I) is not None for term in terms)
    return checks

def native_settings(profile):
    return {"model_factory": "OpenAI-API-Compatible", "model_name": profile["model"],
            "display_name": profile["model"], "model_type": "llm", "base_url": profile["base_url"],
            "context_window_tokens": 16384, "max_output_tokens": 1024, "default_output_reserve_tokens": 1024,
            "temperature": .1, "timeout_seconds": 60, "concurrency_limit": 1,
            "extra_params": {"enable_thinking": False, "__custom__": {"thinking": {"type": "disabled"}}},
            "skip_default_backfill": True}

def bind_drafts(api, profile, key, saved):
    """Migrate only the six scoped workflow drafts, never unrelated published agents."""
    # Reject active agents before making any model/agent changes.
    for role, agent_id in saved["agents"].items():
        info = api.call("POST", "/agent/search_info", {"agent_id": agent_id, "version_no": 0})
        versions = api.call("GET", f"/agent/{agent_id}/versions")
        if info["name"] != "govflow_"+role or info.get("enabled") is not False or versions.get("total", 0):
            raise CloudError("REFUSE_TO_OVERWRITE_ACTIVE_AGENT")
    models = api.call("GET", "/model/list")["data"]
    found = [m for m in models if m["display_name"] == profile["model"]]
    if len(found) > 1: raise CloudError("AMBIGUOUS_NATIVE_MODEL")
    if found:
        if found[0]["model_name"] != profile["model"] or found[0]["base_url"] != profile["base_url"]:
            raise CloudError("NATIVE_MODEL_PROFILE_CONFLICT")
        # Preserve a verified model's context settings and credential. Rotating
        # credentials is a separate operation, not a side effect of draft wiring.
    else:
        api.call("POST", "/model/create", {**native_settings(profile), "api_key": key})
    models = api.call("GET", "/model/list")["data"]
    model = next(m for m in models if m["display_name"] == profile["model"])
    if model.get("connect_status") != "available":
        raise CloudError("NATIVE_MODEL_HEALTHCHECK_REQUIRED")
    model_id = model["model_id"]
    bindings = {}
    for role, agent_id in saved["agents"].items():
        api.call("POST", "/agent/update", {"agent_id": agent_id, "enabled": False, "model_ids": [model_id],
            "model_params_override": {str(model_id): {"temperature": .1, "extra_params": native_settings(profile)["extra_params"]}}})
        info = api.call("POST", "/agent/search_info", {"agent_id": agent_id, "version_no": 0})
        if info["model_ids"] != [model_id] or info["enabled"] is not False: raise CloudError("NATIVE_BINDING_NOT_VERIFIED")
        bindings[role] = {"agent_id": agent_id, "model_id": model_id, "model": profile["model"], "published": False}
    return bindings

"""User-started administrator invitation for manual registration in the local UI."""

import json
from urllib.parse import quote

from nexent_api import NexentAPI, RUNTIME, save_state
from private_runtime import ensure_private_directory


def create_invite(api, runtime=RUNTIME, persist_state=save_state):
    ensure_private_directory(runtime)
    accounts = json.loads((runtime / "accounts.json").read_text(encoding="utf-8"))
    user = api.login(accounts["super_admin"])
    if user.get("user_role") != "SU":
        raise RuntimeError("The bootstrap account must have the native SU role")
    path = runtime / "nexent-state.json"
    state = json.loads(path.read_text(encoding="utf-8")) if path.exists() else {"accounts": {}, "models": {}}
    if "tenant_id" not in state:
        tenant = api.call("POST", "/tenants", {
            "tenant_name": "ICT空白工程验证", "skill_ids": [], "skill_names": [], "locale": "zh"
        })["data"]
        state.update(tenant_id=tenant["tenant_id"], group_id=int(tenant["default_group_id"]))
        persist_state(state)
    invitation_path = runtime / "manual-admin-invitation.json"
    if invitation_path.exists():
        previous = json.loads(invitation_path.read_text(encoding="utf-8"))
        if previous.get("tenant_id") == state["tenant_id"] and previous.get("code_type") == "ADMIN_INVITE":
            code = previous["invitation_code"]
            available = api.call("GET", "/invitations/" + quote(code, safe="") + "/available")["data"]["available"]
            if available:
                return code
    invitation = api.call("POST", "/invitations", {
        "tenant_id": state["tenant_id"], "code_type": "ADMIN_INVITE",
        "group_ids": [state["group_id"]], "capacity": 1
    })["data"]
    record = {"tenant_id": state["tenant_id"], "code_type": "ADMIN_INVITE",
              "invitation_code": invitation["invitation_code"], "capacity": 1}
    pending = invitation_path.with_suffix(".json.part")
    pending.write_text(json.dumps(record, indent=2), encoding="utf-8")
    pending.replace(invitation_path)
    return record["invitation_code"]


def main():
    api = NexentAPI()
    try:
        code = create_invite(api)
        print(f"Invitation code (one registration): {code}")
        print("Paste this code into the registration form at http://127.0.0.1:3000/zh.")
        print("Your email and password are entered by you in the UI; this script does not register them.")
    finally:
        api.close()


if __name__ == "__main__":
    main()

