"""Download pinned official Ollama blobs through the configured HTTP proxy.

This importer verifies registry digests and restricts redirects to the official
registry storage domain. It never disables Ollama's redirect protection.
"""

import argparse
import hashlib
import json
import os
import time
import urllib.error
import urllib.parse
import urllib.request
from pathlib import Path


REGISTRY = "https://registry.ollama.ai"
TAGS = ("4b-q4_K_M", "8b-q4_K_M")


class OfficialRedirects(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        parsed = urllib.parse.urlparse(newurl)
        host = parsed.hostname or ""
        if parsed.scheme != "https" or not (
            host in ("registry.ollama.ai", "registry.ollama.com")
            or host.endswith(".r2.cloudflarestorage.com")
        ):
            raise RuntimeError("Registry redirect was outside the approved official storage domains")
        return super().redirect_request(req, fp, code, msg, headers, newurl)


def sha256(path):
    digest = hashlib.sha256()
    with path.open("rb") as source:
        for chunk in iter(lambda: source.read(4 * 1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def fetch_blob(opener, root, blob):
    algorithm, digest = blob["digest"].split(":", 1)
    if algorithm != "sha256" or len(digest) != 64 or any(c not in "0123456789abcdef" for c in digest):
        raise ValueError("Invalid registry digest")
    dest = root / "blobs" / f"sha256-{digest}"
    dest.parent.mkdir(parents=True, exist_ok=True)
    if dest.exists() and dest.stat().st_size == blob["size"] and sha256(dest) == digest:
        return
    partial = dest.with_suffix(".part")
    for attempt in range(12):
        offset = partial.stat().st_size if partial.exists() else 0
        if offset == blob["size"]:
            if sha256(partial) == digest:
                partial.replace(dest)
                return
            partial.unlink()
            offset = 0
        headers = {"User-Agent": "gov-blank-model-import/0.1"}
        if offset:
            headers["Range"] = f"bytes={offset}-"
        request = urllib.request.Request(f"{REGISTRY}/v2/library/qwen3/blobs/{blob['digest']}", headers=headers)
        try:
            with opener.open(request, timeout=30) as response:
                resumed = response.status == 206 and response.headers.get("Content-Range", "").startswith(f"bytes {offset}-")
                if response.status not in (200, 206) or (response.status == 206 and not resumed):
                    raise RuntimeError("Invalid registry range response")
                if not resumed:
                    offset = 0
                with partial.open("ab" if resumed else "wb") as target:
                    total = offset
                    announced = total // (128 * 1024 * 1024)
                    while chunk := response.read(4 * 1024 * 1024):
                        target.write(chunk)
                        total += len(chunk)
                        if total > blob["size"]:
                            raise RuntimeError("Blob exceeded its declared registry size")
                        progress = total // (128 * 1024 * 1024)
                        if progress > announced:
                            print(f"blob {digest[:12]}: {total / blob['size']:.0%}", flush=True)
                            announced = progress
            if partial.stat().st_size != blob["size"] or sha256(partial) != digest:
                raise RuntimeError("Blob integrity verification failed")
            partial.replace(dest)
            print(f"verified {digest[:12]} ({blob['size']} bytes)", flush=True)
            return
        except (OSError, urllib.error.URLError, RuntimeError) as exc:
            # Signed redirect URLs and proxy credentials must never enter logs.
            reason = type(getattr(exc, "reason", exc)).__name__
            print(f"blob {digest[:12]} attempt {attempt + 1}/12: {reason}", flush=True)
            if attempt == 11:
                raise RuntimeError(f"Download incomplete for blob {digest[:12]}; partial bytes retained") from None
            time.sleep(2)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--tag", choices=TAGS, action="append")
    parser.add_argument("--output", type=Path, default=Path(os.environ.get("OLLAMA_MODELS", str(Path.home() / ".ollama/models"))))
    parser.add_argument("--evidence", type=Path, default=Path("evidence/model-downloads.json"))
    args = parser.parse_args()
    opener = urllib.request.build_opener(OfficialRedirects())
    records = json.loads(args.evidence.read_text()) if args.evidence.exists() else {}
    for tag in args.tag or TAGS:
        url = f"{REGISTRY}/v2/library/qwen3/manifests/{tag}"
        for attempt in range(3):
            try:
                with opener.open(url, timeout=45) as response:
                    raw = response.read()
                    manifest_digest = response.headers.get("Docker-Content-Digest")
                break
            except OSError:
                if attempt == 2:
                    raise RuntimeError(f"Could not fetch official manifest for qwen3:{tag}") from None
        computed = "sha256:" + hashlib.sha256(raw).hexdigest()
        if manifest_digest and manifest_digest != computed:
            raise RuntimeError("Registry manifest digest mismatch")
        manifest = json.loads(raw)
        print(f"qwen3:{tag}: downloading verified official blobs", flush=True)
        for blob in [manifest["config"], *manifest["layers"]]:
            fetch_blob(opener, args.output, blob)
        dest = args.output / "manifests/registry.ollama.ai/library/qwen3" / tag
        dest.parent.mkdir(parents=True, exist_ok=True)
        pending = dest.with_suffix(".part")
        pending.write_bytes(raw)
        pending.replace(dest)
        records[f"qwen3:{tag}"] = {"manifest_digest": computed, "verified": True, "total_bytes": sum(x["size"] for x in [manifest["config"], *manifest["layers"]])}
        args.evidence.parent.mkdir(parents=True, exist_ok=True)
        args.evidence.write_text(json.dumps(records, indent=2) + "\n")
        print(f"Imported qwen3:{tag}; all blobs SHA-256 verified", flush=True)


if __name__ == "__main__":
    main()

class OfficialRedirects(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        parsed = urllib.parse.urlparse(newurl)
        host = parsed.hostname or ""
        if parsed.scheme != "https" or not (
            host in ("registry.ollama.ai", "registry.ollama.com")
            or host.endswith(".r2.cloudflarestorage.com")
        ):
            raise RuntimeError("Registry redirect was outside the approved official storage domains")
        return super().redirect_request(req, fp, code, msg, headers, newurl)

def redirect_request(self, req, fp, code, msg, headers, newurl):
    parsed = urllib.parse.urlparse(newurl)
    host = parsed.hostname or ""
    if parsed.scheme != "https" or not (
        host in ("registry.ollama.ai", "registry.ollama.com")
        or host.endswith(".r2.cloudflarestorage.com")
    ):
        raise RuntimeError("Registry redirect was outside the approved official storage domains")
    return super().redirect_request(req, fp, code, msg, headers, newurl)

def sha256(path):
    digest = hashlib.sha256()
    with path.open("rb") as source:
        for chunk in iter(lambda: source.read(4 * 1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()

def fetch_blob(opener, root, blob):
    algorithm, digest = blob["digest"].split(":", 1)
    if algorithm != "sha256" or len(digest) != 64 or any(c not in "0123456789abcdef" for c in digest):
        raise ValueError("Invalid registry digest")
    dest = root / "blobs" / f"sha256-{digest}"
    dest.parent.mkdir(parents=True, exist_ok=True)
    if dest.exists() and dest.stat().st_size == blob["size"] and sha256(dest) == digest:
        return
    partial = dest.with_suffix(".part")
    for attempt in range(12):
        offset = partial.stat().st_size if partial.exists() else 0
        if offset == blob["size"]:
            if sha256(partial) == digest:
                partial.replace(dest)
                return
            partial.unlink()
            offset = 0
        headers = {"User-Agent": "gov-blank-model-import/0.1"}
        if offset:
            headers["Range"] = f"bytes={offset}-"
        request = urllib.request.Request(f"{REGISTRY}/v2/library/qwen3/blobs/{blob['digest']}", headers=headers)
        try:
            with opener.open(request, timeout=30) as response:
                resumed = response.status == 206 and response.headers.get("Content-Range", "").startswith(f"bytes {offset}-")
                if response.status not in (200, 206) or (response.status == 206 and not resumed):
                    raise RuntimeError("Invalid registry range response")
                if not resumed:
                    offset = 0
                with partial.open("ab" if resumed else "wb") as target:
                    total = offset
                    announced = total // (128 * 1024 * 1024)
                    while chunk := response.read(4 * 1024 * 1024):
                        target.write(chunk)
                        total += len(chunk)
                        if total > blob["size"]:
                            raise RuntimeError("Blob exceeded its declared registry size")
                        progress = total // (128 * 1024 * 1024)
                        if progress > announced:
                            print(f"blob {digest[:12]}: {total / blob['size']:.0%}", flush=True)
                            announced = progress
            if partial.stat().st_size != blob["size"] or sha256(partial) != digest:
                raise RuntimeError("Blob integrity verification failed")
            partial.replace(dest)
            print(f"verified {digest[:12]} ({blob['size']} bytes)", flush=True)
            return
        except (OSError, urllib.error.URLError, RuntimeError) as exc:
            # Signed redirect URLs and proxy credentials must never enter logs.
            reason = type(getattr(exc, "reason", exc)).__name__
            print(f"blob {digest[:12]} attempt {attempt + 1}/12: {reason}", flush=True)
            if attempt == 11:
                raise RuntimeError(f"Download incomplete for blob {digest[:12]}; partial bytes retained") from None
            time.sleep(2)

def file_sha(path):
    value = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(4 * 1024**2), b""):
            value.update(block)
    return value.hexdigest()

def validate_spec(spec):
    if spec.get("repository") != "Qwen/Qwen3-4B":
        raise ValueError("Only the approved public Qwen3-4B repository is supported")
    names = set()
    for row in spec["files"]:
        name = row["Path"]
        if name in names or not re.fullmatch(r"[A-Za-z0-9_.-]+", name) or name.startswith("."):
            raise ValueError("Invalid or duplicate model filename")
        names.add(name)
        if not re.fullmatch("[a-f0-9]{40}", row["Revision"]) or not re.fullmatch("[a-f0-9]{64}", row["Sha256"]):
            raise ValueError("Invalid pinned revision or digest")
        if type(row["Size"]) is not int or not 0 < row["Size"] <= 5 * 1024**3:
            raise ValueError("Invalid model file size")
    required = {"config.json", "tokenizer_config.json", "tokenizer.json", "model.safetensors.index.json"}
    if not required <= names or len([n for n in names if n.endswith(".safetensors")]) != 3:
        raise ValueError("Incomplete pinned Qwen3-4B file list")

def verify_base(directory: Path, spec: dict):
    validate_spec(spec)
    for row in spec["files"]:
        path = directory / row["Path"]
        if not path.is_file() or path.stat().st_size != row["Size"] or file_sha(path) != row["Sha256"]:
            raise ValueError("Base file missing or integrity mismatch: " + row["Path"])
    cfg = json.loads((directory / "config.json").read_bytes())
    if cfg.get("model_type") != "qwen3" or cfg.get("architectures") != ["Qwen3ForCausalLM"]:
        raise ValueError("Unexpected base model architecture")

def download_file(directory, row, direct):
    target = directory / row["Path"]
    if target.exists():
        if target.stat().st_size == row["Size"] and file_sha(target) == row["Sha256"]:
            print(json.dumps({"file": row["Path"], "status": "verified_cached"}), flush=True)
            return
        raise ValueError("Existing final model file has wrong digest; refusing to overwrite it")
    partial = target.with_name(target.name + ".part")
    position = partial.stat().st_size if partial.exists() else 0
    url = ("https://modelscope.cn/models/Qwen/Qwen3-4B/resolve/" + row["Revision"] + "/" + row["Path"])
    headers = {"User-Agent": "govkb-local-qwen-training/1.0"}
    if position:
        headers["Range"] = f"bytes={position}-"
    opener = urllib.request.build_opener(urllib.request.ProxyHandler({})) if direct else urllib.request.build_opener()
    if position < row["Size"]:
        with opener.open(urllib.request.Request(url, headers=headers), timeout=30) as response:
            mode = "ab" if position and response.status == 206 else "wb"
            if mode == "ab" and not response.headers.get("Content-Range", "").startswith(f"bytes {position}-"):
                raise ValueError("Invalid resumed content range")
            if mode == "wb":
                position = 0
            printed = position
            with partial.open(mode) as stream:
                for block in iter(lambda: response.read(4 * 1024**2), b""):
                    position += len(block)
                    if position > row["Size"]:
                        raise ValueError("Downloaded content exceeds pinned size")
                    stream.write(block)
                    if position - printed >= 256 * 1024**2:
                        print(json.dumps({"file": row["Path"], "downloaded_mib": position // 1024**2,
                                          "total_mib": row["Size"] // 1024**2}), flush=True)
                        printed = position
    if partial.stat().st_size != row["Size"] or file_sha(partial) != row["Sha256"]:
        raise ValueError("Downloaded model integrity mismatch: " + row["Path"])
    partial.replace(target)
    print(json.dumps({"file": row["Path"], "status": "sha256_verified"}), flush=True)

def main():
    private = RUNTIME / "asset-query"
    saved = json.loads((private / "nexent.json").read_text(encoding="utf-8"))
    api = NexentAPI()
    report = {"captured_at": datetime.now(timezone.utc).isoformat(), "passed": False}
    try:
        api.login(json.loads((RUNTIME / "accounts.json").read_text(encoding="utf-8"))["developer"])
        response = api.http.post(api.base + "/agent/export", headers={"Authorization": "Bearer " + api.token}, json={"agent_id": saved["agent_id"]})
        response.raise_for_status()
        data = response.content
        (private / "agent-export.zip").write_bytes(data)
        def skill_parts(text):
            _prefix, frontmatter, body = text.replace("\r\n", "\n").split("---", 2)
            return yaml.safe_load(frontmatter), body.strip()
        expected = skill_parts((ROOT / "config/skills/govdocs-evidence-query/SKILL.md").read_text(encoding="utf-8"))
        verified = False
        with zipfile.ZipFile(io.BytesIO(data)) as outer:
            if outer.testzip() is not None or "agent.json" not in outer.namelist():
                raise ValueError("Invalid outer export")
            for name in outer.namelist():
                if name.startswith("skills/") and name.endswith(".zip"):
                    with zipfile.ZipFile(io.BytesIO(outer.read(name))) as inner:
                        if inner.testzip() is not None:
                            raise ValueError("Invalid Skill archive")
                        for member in inner.namelist():
                            if member.endswith("SKILL.md") and skill_parts(inner.read(member).decode("utf-8")) == expected:
                                verified = True
            report["archive_members"] = outer.namelist()
        if not verified:
            raise ValueError("Actual Skill content not found in export")
        report.update(passed=True, agent_id=saved["agent_id"], skill_id=saved["skill_id"], version_no=saved["version_no"],
                      exported_skill_content_verified=True, bytes=len(data), sha256=hashlib.sha256(data).hexdigest(),
                      storage="private .runtime/asset-query/agent-export.zip; connection settings must be reviewed before sharing")
    except Exception as error:
        report["error_type"] = type(error).__name__
    finally:
        api.close()
        destination = ROOT / "evidence/asset-query/export-20261015.json"
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding="utf-8")
        print(json.dumps({"passed": report["passed"], "summary": str(destination)}))
    return 0 if report["passed"] else 1

def skill_parts(text):
    _prefix, frontmatter, body = text.replace("\r\n", "\n").split("---", 2)
    return yaml.safe_load(frontmatter), body.strip()

def semantic_screening_for_review(reference, registry):
    path = ROOT / "evaluation/knowledge/holdout-semantic-screening.json"
    if not path.exists():
        return {"status": "missing", "assessment": None, "batch_ready_for_freeze": False}
    review = json.loads(path.read_text(encoding="utf-8"))
    if (review.get("kind") != "ai_semantic_screening_not_acceptance"
            or fingerprint({k: v for k, v in review.items() if k != "content_sha256"}) != review.get("content_sha256")
            or any(review.get(k) is not False for k in ("batch_ready_for_freeze", "independence_certified",
                                                        "business_acceptance_executed"))):
        raise ValueError("Semantic screening is damaged or claims acceptance")
    from gov_mcp.knowledge_review import question_fingerprint
    questions = [{"id": c["id"], "question_sha256": question_fingerprint(c["question"]), "query_date": c["query_date"]}
                 for c in reference["cases"]]
    screened = [{k: c[k] for k in ("id", "question_sha256", "query_date")} for c in review["cases"]]
    file_checks = {}
    for name, artifacts in (("development_files_match", review["development_sources"]),
                            ("history_artifacts_match", review.get("history_artifacts", []))):
        match = True
        for source in artifacts:
            source_path = (ROOT / source["path"]).resolve()
            if not source_path.is_relative_to(ROOT.resolve()):
                raise ValueError("Review artifact must stay inside this project")
            match &= source_path.is_file() and fingerprint(source_path.read_bytes()) == source["sha256"]
        file_checks[name] = match
    checks = {"questions_match": screened == questions and fingerprint(questions) == review["question_set_sha256"],
              "development_registry_matches": fingerprint(registry) == review["development_registry_sha256"],
              **file_checks}
    if reference.get("draft_revision", 2) >= 3:
        from holdout_provenance import migration_path, semantic_projection, sealed
        migration = json.loads((ROOT / migration_path(reference)).read_text(encoding="utf-8"))
        checks.update(reference_contents_match=fingerprint({k:v for k,v in reference.items() if k != "content_sha256"}) == review.get("reference_contents_sha256"),
                      reference_semantics_match=fingerprint(semantic_projection(reference)) == review.get("reference_semantics_sha256"),
                      provenance_migration_matches=sealed(migration) and migration["content_sha256"] == review.get("provenance_migration_sha256"))
    bound = all(checks.values())
    return {"status": "bound" if bound else "stale", "artifact_sha256": fingerprint(path.read_bytes()),
            "binding_checks": checks, "assessment": review if bound else None, "batch_ready_for_freeze": False,
            "warning": "Retired questions cannot count toward acceptance. Retained questions only continue source review. Stale judgments are withheld; no automatic freeze or acceptance."}

"""Strict v2-to-v3 source migration; this never certifies reference truth."""

import json
import re
import unicodedata
from pathlib import Path

from gov_mcp.knowledge import fingerprint


ARCHIVE = Path("evaluation/knowledge/archive/holdout-v2-before-service-review-20261017")
MIGRATION = Path("evaluation/knowledge/holdout-provenance-migration-v3.json")
STALE_RECEIPT = Path("evidence/knowledge-update/archive/holdout-v2-stale-integrity-20261017.json")
PROVENANCE_FIELDS = {"background_source_anchors", "proposed_relevant_evidence"}
TOP_FIELDS = {"draft_revision", "sources", "cases", "provenance_migration",
              "provenance_migrated_at", "freeze_blockers", "content_sha256"}


def read(path):
    return json.loads(Path(path).read_text(encoding="utf-8"))


def sealed(value):
    return fingerprint({k:v for k,v in value.items() if k != "content_sha256"}) == value.get("content_sha256")


def semantic_projection(reference):
    return [{k:v for k,v in c.items() if k not in PROVENANCE_FIELDS} for c in reference["cases"]]


def validate_semantics(before, after):
    changed = {k for k in before.keys() | after.keys() if before.get(k) != after.get(k)}
    if (before["draft_revision"] != 2 or after["draft_revision"] != 3 or not changed <= TOP_FIELDS
            or semantic_projection(before) != semantic_projection(after)
            or len(before["cases"]) != 30 or len({c["id"] for c in before["cases"]}) != 30
            or any(after.get(k) is not False for k in ("independent_acceptance_ready", "independence_certified",
                                                       "human_review_completed", "ready_for_business_publication"))
            or any(after.get(k) is not None for k in ("reference_frozen_at", "snapshot_binding", "observed_run"))
            or after["freeze_blockers"][1:] != before["freeze_blockers"][1:]
            or len(after["freeze_blockers"]) != 4 or not after["freeze_blockers"][0]):
        raise ValueError("Provenance migration cannot change questions, oracles, design, authorship or acceptance")


def archive_reference(root):
    manifest = read(root / ARCHIVE / "manifest.json")
    if not sealed(manifest) or manifest["source_commit"] != "cad63175ba610148bed43b4d1dfb3627b545408e":
        raise ValueError("Expected intact v2 archive")
    for item in manifest["files"]:
        path = (root / item["path"]).resolve()
        if path.parent != (root / ARCHIVE).resolve() or fingerprint(path.read_bytes()) != item["sha256"]:
            raise ValueError("Archived v2 bytes differ")
    before = read(root / ARCHIVE / "holdout-business-reference-draft.json")
    if not sealed(before):
        raise ValueError("Archived v2 reference is damaged")
    return before, manifest


def source_binding(store, db, source_id, url, revision=None):
    sql = "SELECT r.* FROM revisions r JOIN documents d ON d.id=r.document_id WHERE d.site_id=? AND d.url=?"
    args = [source_id,url]
    if revision is not None:
        sql += " AND r.id=?"
        args.append(revision)
    row = db.execute(sql+" ORDER BY r.rowid DESC LIMIT 1", args).fetchone()
    if row is None or row["state"] not in ("pending_review", "reviewed"):
        raise ValueError("Expected available source candidate")
    approved = row["state"] == "reviewed"
    store._verify(db,row["id"],require_review=approved)
    result = {"source_id":source_id,"url":url,"revision":row["id"],"original_sha256":row["sha256"],
              "body_sha256":row["body_sha256"],"metadata_sha256":fingerprint(row["metadata"].encode()),
              "state":row["state"],"business_approval":approved}
    if approved:
        result["recorded_review"] = dict(db.execute("SELECT reviewer,digest,reviewed_at FROM reviews WHERE revision_id=?", (row["id"],)).fetchone())
    return result


def full_anchor(db, key, revision, locator):
    chunk = db.execute("SELECT ordinal,text FROM chunks WHERE revision_id=? AND locator=?", (revision,locator)).fetchone()
    if chunk is None:
        raise ValueError("Migration requires a literal source locator")
    text = chunk["text"]
    return {"source_key":key,"revision":revision,"locator":locator,"ordinal":chunk["ordinal"],
            "start":0,"end":len(text),"parent_text_sha256":fingerprint(text.encode()),"span_sha256":fingerprint(text.encode())}


def expected_anchors(db, before_case, after_sources):
    result = []
    for anchor in before_case["background_source_anchors"]:
        if before_case["id"] == "HB06" and (anchor["source_key"],anchor["locator"]) == ("D26","正文段落2"):
            continue
        if anchor["source_key"] in ("D26", "LAW"):
            result.append(full_anchor(db,anchor["source_key"],after_sources[anchor["source_key"]]["revision"],anchor["locator"]))
        else:
            result.append(anchor)
    return result


def migration_evidence(store, db, before, after):
    validate_semantics(before,after)
    if (set(before["sources"]) != set(after["sources"])
            or any(before["sources"][k] != after["sources"][k] for k in before["sources"] if k not in ("D26","LAW"))):
        raise ValueError("Only D26 and LAW provenance may migrate")
    comparisons = {}
    norm = lambda text: re.sub(r"\s+", "", unicodedata.normalize("NFKC",text))
    for key in ("D26","LAW"):
        old,new = before["sources"][key],after["sources"][key]
        if (key == "D26" and (new["source_id"],new["url"]) != (old["source_id"],old["url"])) or (
                key == "LAW" and (new["source_id"],new["url"]) != ("ID-AMENDMENT-JT-LEAD","https://jtgl.beijing.gov.cn/jgj/jgxx/flfg/fl/203777/index.html")):
            raise ValueError("Unexpected replacement source")
        if source_binding(store,db,new["source_id"],new["url"],new["revision"]) != new or new["business_approval"] is not True:
            raise ValueError("Migrated source must match its actual recorded review")
        store._verify(db,old["revision"],require_review=False)
        _,old_chunks = store._content(db,old["revision"])
        _,new_chunks = store._content(db,new["revision"])
        if key == "D26":
            if (len(old_chunks) != 2 or new_chunks != old_chunks[:1]
                    or old["original_sha256"] != new["original_sha256"]):
                raise ValueError("Only the intact first service measure may replace the old two paragraphs")
            comparisons[key] = {"kind":"same_original_complete_first_measure", "retained_locator":"正文段落1",
                "removed_background_locator":"正文段落2","original_sha256":new["original_sha256"]}
        else:
            if len(old_chunks) != 23 or len(new_chunks) != 23 or [(c["locator"],norm(c["text"])) for c in old_chunks] != [(c["locator"],norm(c["text"])) for c in new_chunks]:
                raise ValueError("All 23 legal clauses must match under NFKC and whitespace normalization")
            comparisons[key] = {"kind":"same_23_clauses_other_official_original", "normalization":"NFKC_then_remove_whitespace",
                "clauses":[{"locator":a["locator"],"before_text_sha256":fingerprint(a["text"].encode()),
                            "after_text_sha256":fingerprint(b["text"].encode()),"normalized_sha256":fingerprint(norm(a["text"]).encode()),
                            "literal_equal":a["text"] == b["text"]} for a,b in zip(old_chunks,new_chunks,strict=True)]}
    records = []
    for old,new in zip(before["cases"],after["cases"],strict=True):
        for anchor in old["background_source_anchors"]:
            if anchor != full_anchor(db,anchor["source_key"],anchor["revision"],anchor["locator"]):
                raise ValueError("The archived v2 anchor must remain an exact complete source span")
        anchors = expected_anchors(db,old,after["sources"])
        relevant = [] if old["proposed_outcome_after_qualified_publication"] == "stop" else [{"revision":a["revision"],"locator":a["locator"]} for a in anchors]
        if new["background_source_anchors"] != anchors or new["proposed_relevant_evidence"] != relevant:
            raise ValueError("Unexpected evidence insertion, removal or source-span change")
        records.append({"id":old["id"],"before_sha256":fingerprint(old),"after_sha256":fingerprint(new),
                        "changed_fields":sorted(k for k in old.keys() | new.keys() if old.get(k) != new.get(k))})
    return {"before_reference_sha256":before["content_sha256"],"after_reference_sha256":after["content_sha256"],
            "case_semantics_sha256":fingerprint(semantic_projection(after)),"sources":comparisons,"cases":records,
            "explicit_evidence_removals":[{"case_id":"HB06","source_key":"D26","locator":"正文段落2",
                "reason":"Explanatory background is outside the approved service selection. The complete first measure already states both duration branches; the unchanged reference does not assert a statutory natural-day calculation."}]}


def validate_migration(root,store,db,reference):
    if reference.get("draft_revision") == 5:
        from holdout_provenance_v5 import validate_v5_migration
        return validate_v5_migration(root,store,db,reference)
    if reference.get("draft_revision") == 4:
        from holdout_provenance_v4 import validate_v4_migration
        return validate_v4_migration(root,store,db,reference)
    if reference.get("draft_revision") == 2:
        return reference
    if reference.get("provenance_migration") != {"path":MIGRATION.as_posix()} or not sealed(reference):
        raise ValueError("Expected explicitly bound v3 migration")
    before,manifest = archive_reference(root)
    ledger = read(root / MIGRATION)
    stale = read(root / STALE_RECEIPT)
    if (not sealed(ledger) or ledger.get("kind") != "holdout_provenance_migration_not_acceptance"
            or ledger.get("base_archive_manifest_sha256") != manifest["content_sha256"]
            or ledger.get("human_review_completed") is not False or ledger.get("acceptance_authorized") is not False
            or ledger.get("reviewer") != "Codex AI"
            or ledger.get("previous_integrity_report") != {"path":STALE_RECEIPT.as_posix(),"sha256":fingerprint((root/STALE_RECEIPT).read_bytes())}
            or stale.get("draft_integrity_passed") is not False
            or sorted(k for k,v in stale["checks"].items() if not v) != sorted(["latest_originals_and_literal_anchor_spans_match",
                "actual_export_contains_both_drafts_and_preserves_empty_approvals"])
            or ledger.get("evidence") != migration_evidence(store,db,before,reference)):
        raise ValueError("Migration ledger differs from actual source or unchanged case semantics")
    return before


def migration_path(reference):
    """Resolve only a known, explicitly bound migration, never an arbitrary path."""
    if reference.get("draft_revision") == 3:
        expected = MIGRATION
    elif reference.get("draft_revision") == 4:
        from holdout_provenance_v4 import MIGRATION_V4
        expected = MIGRATION_V4
    elif reference.get("draft_revision") == 5:
        from holdout_provenance_v5 import MIGRATION_V5
        expected = MIGRATION_V5
    else:
        raise ValueError("Unsupported provenance migration version")
    if reference.get("provenance_migration") != {"path":expected.as_posix()}:
        raise ValueError("Unexpected provenance migration path")
    return expected

def archive_reference(root):
    manifest = read(root / ARCHIVE / "manifest.json")
    if not sealed(manifest) or manifest["source_commit"] != "cad63175ba610148bed43b4d1dfb3627b545408e":
        raise ValueError("Expected intact v2 archive")
    for item in manifest["files"]:
        path = (root / item["path"]).resolve()
        if path.parent != (root / ARCHIVE).resolve() or fingerprint(path.read_bytes()) != item["sha256"]:
            raise ValueError("Archived v2 bytes differ")
    before = read(root / ARCHIVE / "holdout-business-reference-draft.json")
    if not sealed(before):
        raise ValueError("Archived v2 reference is damaged")
    return before, manifest

def full_anchor(db, key, revision, locator):
    chunk = db.execute("SELECT ordinal,text FROM chunks WHERE revision_id=? AND locator=?", (revision,locator)).fetchone()
    if chunk is None:
        raise ValueError("Migration requires a literal source locator")
    text = chunk["text"]
    return {"source_key":key,"revision":revision,"locator":locator,"ordinal":chunk["ordinal"],
            "start":0,"end":len(text),"parent_text_sha256":fingerprint(text.encode()),"span_sha256":fingerprint(text.encode())}

def expected_anchors(db, before_case, after_sources):
    result = []
    for anchor in before_case["background_source_anchors"]:
        if before_case["id"] == "HB06" and (anchor["source_key"],anchor["locator"]) == ("D26","正文段落2"):
            continue
        if anchor["source_key"] in ("D26", "LAW"):
            result.append(full_anchor(db,anchor["source_key"],after_sources[anchor["source_key"]]["revision"],anchor["locator"]))
        else:
            result.append(anchor)
    return result

def migration_evidence(store, db, before, after):
    validate_semantics(before,after)
    if (set(before["sources"]) != set(after["sources"])
            or any(before["sources"][k] != after["sources"][k] for k in before["sources"] if k not in ("D26","LAW"))):
        raise ValueError("Only D26 and LAW provenance may migrate")
    comparisons = {}
    norm = lambda text: re.sub(r"\s+", "", unicodedata.normalize("NFKC",text))
    for key in ("D26","LAW"):
        old,new = before["sources"][key],after["sources"][key]
        if (key == "D26" and (new["source_id"],new["url"]) != (old["source_id"],old["url"])) or (
                key == "LAW" and (new["source_id"],new["url"]) != ("ID-AMENDMENT-JT-LEAD","https://jtgl.beijing.gov.cn/jgj/jgxx/flfg/fl/203777/index.html")):
            raise ValueError("Unexpected replacement source")
        if source_binding(store,db,new["source_id"],new["url"],new["revision"]) != new or new["business_approval"] is not True:
            raise ValueError("Migrated source must match its actual recorded review")
        store._verify(db,old["revision"],require_review=False)
        _,old_chunks = store._content(db,old["revision"])
        _,new_chunks = store._content(db,new["revision"])
        if key == "D26":
            if (len(old_chunks) != 2 or new_chunks != old_chunks[:1]
                    or old["original_sha256"] != new["original_sha256"]):
                raise ValueError("Only the intact first service measure may replace the old two paragraphs")
            comparisons[key] = {"kind":"same_original_complete_first_measure", "retained_locator":"正文段落1",
                "removed_background_locator":"正文段落2","original_sha256":new["original_sha256"]}
        else:
            if len(old_chunks) != 23 or len(new_chunks) != 23 or [(c["locator"],norm(c["text"])) for c in old_chunks] != [(c["locator"],norm(c["text"])) for c in new_chunks]:
                raise ValueError("All 23 legal clauses must match under NFKC and whitespace normalization")
            comparisons[key] = {"kind":"same_23_clauses_other_official_original", "normalization":"NFKC_then_remove_whitespace",
                "clauses":[{"locator":a["locator"],"before_text_sha256":fingerprint(a["text"].encode()),
                            "after_text_sha256":fingerprint(b["text"].encode()),"normalized_sha256":fingerprint(norm(a["text"]).encode()),
                            "literal_equal":a["text"] == b["text"]} for a,b in zip(old_chunks,new_chunks,strict=True)]}
    records = []
    for old,new in zip(before["cases"],after["cases"],strict=True):
        for anchor in old["background_source_anchors"]:
            if anchor != full_anchor(db,anchor["source_key"],anchor["revision"],anchor["locator"]):
                raise ValueError("The archived v2 anchor must remain an exact complete source span")
        anchors = expected_anchors(db,old,after["sources"])
        relevant = [] if old["proposed_outcome_after_qualified_publication"] == "stop" else [{"revision":a["revision"],"locator":a["locator"]} for a in anchors]
        if new["background_source_anchors"] != anchors or new["proposed_relevant_evidence"] != relevant:
            raise ValueError("Unexpected evidence insertion, removal or source-span change")
        records.append({"id":old["id"],"before_sha256":fingerprint(old),"after_sha256":fingerprint(new),
                        "changed_fields":sorted(k for k in old.keys() | new.keys() if old.get(k) != new.get(k))})
    return {"before_reference_sha256":before["content_sha256"],"after_reference_sha256":after["content_sha256"],
            "case_semantics_sha256":fingerprint(semantic_projection(after)),"sources":comparisons,"cases":records,
            "explicit_evidence_removals":[{"case_id":"HB06","source_key":"D26","locator":"正文段落2",
                "reason":"Explanatory background is outside the approved service selection. The complete first measure already states both duration branches; the unchanged reference does not assert a statutory natural-day calculation."}]}

def validate_migration(root,store,db,reference):
    if reference.get("draft_revision") == 5:
        from holdout_provenance_v5 import validate_v5_migration
        return validate_v5_migration(root,store,db,reference)
    if reference.get("draft_revision") == 4:
        from holdout_provenance_v4 import validate_v4_migration
        return validate_v4_migration(root,store,db,reference)
    if reference.get("draft_revision") == 2:
        return reference
    if reference.get("provenance_migration") != {"path":MIGRATION.as_posix()} or not sealed(reference):
        raise ValueError("Expected explicitly bound v3 migration")
    before,manifest = archive_reference(root)
    ledger = read(root / MIGRATION)
    stale = read(root / STALE_RECEIPT)
    if (not sealed(ledger) or ledger.get("kind") != "holdout_provenance_migration_not_acceptance"
            or ledger.get("base_archive_manifest_sha256") != manifest["content_sha256"]
            or ledger.get("human_review_completed") is not False or ledger.get("acceptance_authorized") is not False
            or ledger.get("reviewer") != "Codex AI"
            or ledger.get("previous_integrity_report") != {"path":STALE_RECEIPT.as_posix(),"sha256":fingerprint((root/STALE_RECEIPT).read_bytes())}
            or stale.get("draft_integrity_passed") is not False
            or sorted(k for k,v in stale["checks"].items() if not v) != sorted(["latest_originals_and_literal_anchor_spans_match",
                "actual_export_contains_both_drafts_and_preserves_empty_approvals"])
            or ledger.get("evidence") != migration_evidence(store,db,before,reference)):
        raise ValueError("Migration ledger differs from actual source or unchanged case semantics")
    return before

def migration_path(reference):
    """Resolve only a known, explicitly bound migration, never an arbitrary path."""
    if reference.get("draft_revision") == 3:
        expected = MIGRATION
    elif reference.get("draft_revision") == 4:
        from holdout_provenance_v4 import MIGRATION_V4
        expected = MIGRATION_V4
    elif reference.get("draft_revision") == 5:
        from holdout_provenance_v5 import MIGRATION_V5
        expected = MIGRATION_V5
    else:
        raise ValueError("Unsupported provenance migration version")
    if reference.get("provenance_migration") != {"path":expected.as_posix()}:
        raise ValueError("Unexpected provenance migration path")
    return expected

def literal_anchors(db, before_case, after_sources, source_keys=None):
    anchors = []
    for original in before_case["background_source_anchors"]:
        if original != full_anchor(db, original["source_key"], original["revision"], original["locator"]):
            raise ValueError("Expected an intact complete historical source span")
        anchor = deepcopy(original)
        if anchor["source_key"] in (EXPECTED_REVISIONS if source_keys is None else source_keys):
            revision = after_sources[anchor["source_key"]]["revision"]
            matches = [row for row in db.execute("SELECT ordinal,locator,text FROM chunks WHERE revision_id=?", (revision,))
                       if row["locator"] == anchor["locator"] and fingerprint(row["text"].encode()) == anchor["parent_text_sha256"]
                       and fingerprint(row["text"][anchor["start"]:anchor["end"]].encode()) == anchor["span_sha256"]]
            if len(matches) != 1:
                raise ValueError("Each v4 anchor requires one unchanged literal parent and span")
            anchor.update(revision=revision, ordinal=matches[0]["ordinal"])
        anchors.append(anchor)
    return anchors

def v4_evidence(store, db, before, after):
    validate_v4_semantics(before, after)
    if (set(before["sources"]) != set(after["sources"])
            or any(before["sources"][key] != after["sources"][key] for key in before["sources"] if key not in EXPECTED_REVISIONS)):
        raise ValueError("Only NATIONAL, F18 and WINDOW provenance may migrate")
    comparisons = {}
    for key, revision in EXPECTED_REVISIONS.items():
        old, new = before["sources"][key], after["sources"][key]
        if (new["revision"] != revision or (old["source_id"], old["url"]) != (new["source_id"], new["url"])
                or old["original_sha256"] != new["original_sha256"]
                or source_binding(store, db, new["source_id"], new["url"], revision) != new
                or new["business_approval"] is not True):
            raise ValueError("Migrated source requires its actual scoped review and original")
        old_row, old_chunks = store._content(db, old["revision"])
        new_row, new_chunks = store._content(db, revision)
        store._verify(db, old_row["id"], require_review=False)
        if key == "NATIONAL":
            if (len(old_chunks) != 11 or len(new_chunks) != 10
                    or [c for c in old_chunks if c["locator"] != "第七十六条"] != new_chunks):
                raise ValueError("Only the unreferenced national window clause may be removed")
            watch, watch_chunks = store._content(db, "rev-84412d6b0b512caf0cbe1a01")
            store._verify(db, watch["id"], require_review=False)
            if (watch["state"] != "pending_review" or watch["sha256"] != old_row["sha256"]
                    or watch_chunks != [c for c in old_chunks if c["locator"] == "第七十六条"]):
                raise ValueError("The unresolved national window clause must remain separately pending")
            comparisons[key] = {"kind": "same_original_ten_complete_clauses", "removed_unreferenced_locator": "第七十六条",
                                "pending_window_watch_revision": watch["id"]}
        else:
            if old_chunks != new_chunks or len(new_chunks) != 1:
                raise ValueError("Fee and service-window literal selections must remain identical")
            comparisons[key] = {"kind": "same_original_same_complete_paragraph", "locator": new_chunks[0]["locator"]}
        comparisons[key].update(before_revision=old["revision"], after_revision=revision,
            original_sha256=new["original_sha256"], before_body_sha256=old_row["body_sha256"], after_body_sha256=new_row["body_sha256"],
            actual_review_digest=new["recorded_review"]["digest"])
    cases = []
    for old, new in zip(before["cases"], after["cases"], strict=True):
        expected = literal_anchors(db, old, after["sources"])
        relevant = [] if old["proposed_outcome_after_qualified_publication"] == "stop" else [{"revision":a["revision"], "locator":a["locator"]} for a in expected]
        if new["background_source_anchors"] != expected or new["proposed_relevant_evidence"] != relevant:
            raise ValueError("v4 cannot insert, remove or alter evidence spans")
        cases.append({"id":old["id"], "before_sha256":fingerprint(old), "after_sha256":fingerprint(new),
                      "changed_fields":sorted(k for k in old.keys() | new.keys() if old.get(k) != new.get(k))})
    return {"before_reference_sha256":before["content_sha256"], "after_reference_sha256":after["content_sha256"],
            "case_semantics_sha256":fingerprint(semantic_projection(after)), "sources":comparisons, "cases":cases,
            "literal_span_changes":0, "evidence_insertions_or_removals":0}

