    mode.add_argument("--prepare", action="store_true", help="Fetch only the two fixed official public pages; no model calls")
    mode.add_argument("--live", action="store_true", help="Explicit public cloud consent: one extraction, bounded translation, one Jev HTTP attempt")
    parser.add_argument("--resume", help="Reuse an exact saved extraction against unchanged public sources; requires --live")
    args = parser.parse_args()
    if args.prepare:
        if args.resume:
            parser.error("--resume requires --live")
        prepare()
        return 0
    return run(args.resume)

def assess(events, audit, role, principal):
    errors = []
    tools = [event.get("tool_name") for event in events if event.get("type") == "tool"]
    if tools != ["read_skill_md", "get_environment_status"]:
        errors.append("SKILL_MCP_ORDER_MISMATCH")
    if len(audit) != 1 or audit[0].get("tool") != "get_environment_status":
        errors.append("MCP_AUDIT_COUNT_MISMATCH")
    if any(row.get("principal_sha256") != principal for row in audit):
        errors.append("TRUSTED_IDENTITY_MISMATCH")
    if any(event.get("type") in ("error", "max_steps_reached") for event in events):
        errors.append("RUNTIME_ERROR")
    finals = [event.get("content") for event in events if event.get("type") == "final_answer" and not event.get("depth", 0)]
    result = None
    try:
        result = finals[0] if len(finals) == 1 and isinstance(finals[0], dict) else json.loads("".join(finals))
        if not audit or result != audit[-1]["result"] or result.get("message_code") != "ENVIRONMENT_READY":
            errors.append("FINAL_RESULT_MISMATCH")
    except (ValueError, TypeError, KeyError):
        errors.append("FINAL_RESULT_INVALID")
    return {"passed": not errors, "stop_reasons": errors or ["SKILL_AND_MCP_VERIFIED"], "result": result}

def mount_overlay(content, source):
    # Only this known SDK module is mounted; official source and SQL stay intact.
    mount = f'      - "{source.as_posix()}:{TARGET}:ro" # ICT connection error overlay\n'
    if mount in content:
        return content
    anchor = "  nexent-runtime:\n"
    start = content.find(anchor)
    if start < 0:
        return content
    end = content.find("\n  nexent-", start + len(anchor))
    end = len(content) if end < 0 else end
    pos = content.find("    volumes:\n", start, end)
    if pos < 0:
        raise ValueError("Pinned runtime volume boundary is missing")
    pos += len("    volumes:\n")
    return content[:pos] + mount + content[pos:]

"""Recover only the pinned, system-owned lightweight runtime sandbox."""

import json
import shutil
import subprocess

NAME = "nexent-runtime-sandbox"
IMAGE = "nexent/nexent-sandbox:v2.7.0"


def inspect_sandbox(docker):
    result = subprocess.run([docker, "container", "inspect", NAME], capture_output=True, text=True, timeout=10)
    if result.returncode:
        # A missing container is normal before the first Agent run. Engine errors
        # must not be mistaken for that initial state.
        if "No such container" in result.stderr or "No such object" in result.stderr:
            return None
        raise RuntimeError("Cannot inspect the runtime sandbox")
    value = json.loads(result.stdout)[0]
    labels = value["Config"].get("Labels") or {}
    if (value["Config"]["Image"] != IMAGE or labels.get("com.nexent.sandbox") != "runtime"
            or labels.get("io.nexent.sandbox.variant") != "lightweight"):
        raise RuntimeError("Runtime sandbox identity differs from the pinned deployment")
    return value


def sandbox_ready():
    docker = shutil.which("docker")
    if not docker:
        return False
    try:
        value = inspect_sandbox(docker)
        return value is None or value["State"]["Status"] == "running"
    except (OSError, ValueError, KeyError, RuntimeError, subprocess.SubprocessError):
        return False


def recover_sandbox():
    docker = shutil.which("docker")
    if not docker:
        raise RuntimeError("Docker CLI is required")
    value = inspect_sandbox(docker)
    if value is None:
        return "NOT_CREATED"
    status = value["State"]["Status"]
    if status not in ("running", "exited", "created"):
        raise RuntimeError("Runtime sandbox cannot be recovered from its current state")
    if value["HostConfig"]["RestartPolicy"]["Name"] == "no":
        subprocess.run([docker, "update", "--restart", "unless-stopped", NAME], capture_output=True, check=True, timeout=10)
    if status != "running":
        subprocess.run([docker, "start", NAME], capture_output=True, check=True, timeout=30)
    if inspect_sandbox(docker)["State"]["Status"] != "running":
        raise RuntimeError("Runtime sandbox did not start")
    return "RUNNING"


