        except (OSError, ValueError, sqlite3.Error):
            return result("ERROR", "CONFIG_OR_STORAGE_UNAVAILABLE")
        return result("ERROR", "UNEXPECTED_STOP")

    def get_environment_status(self, tenant_id: str, user_id: str) -> dict:
        return self._run(
            tenant_id, user_id,
            lambda role, counts: result(
                "OK", "ENVIRONMENT_READY", role=role,
                resources={name: {"configured": True, "count": count} for name, count in counts.items()},
            ),
        )

    def search_evidence(self, tenant_id: str, user_id: str) -> dict:
        return self._run(tenant_id, user_id, lambda role, counts: result("EMPTY", "NO_KNOWLEDGE"))

    def check_case_prerequisites(self, tenant_id: str, user_id: str) -> dict:
        return self._run(
            tenant_id, user_id,
            lambda role, counts: result("BLOCKED", "FORBIDDEN") if role != "staff" else
            result("BLOCKED", "MISSING_CASE_AND_MATERIALS", missing=["case", "materials", "evidence"]),
        )

def role(self, tenant_id: str, user_id: str) -> str | None:
    if not tenant_id or not user_id:
        return None
    # Read each time so account provisioning does not require a restart.
    roles = json.loads(self.role_map_path.read_text(encoding="utf-8"))
    if not isinstance(roles, dict) or any(not isinstance(value, dict) for value in roles.values()):
        raise ValueError("Role map must contain tenant-to-user mappings")
    role = roles.get(tenant_id, {}).get(user_id)
    return role if role in ("citizen", "staff") else None

def _run(self, tenant_id: str, user_id: str, fn: Callable) -> dict:
    try:
        role = self.role(tenant_id, user_id)
        if not role:
            return result("BLOCKED", "ROLE_NOT_CONFIGURED")
        for attempt in range(2):
            try:
                counts = self.store.counts()
                # Refuse to use any accidentally populated data in this phase.
                if any(counts.values()):
                    return result("ERROR", "BLANK_BOUNDARY_VIOLATED")
                return fn(role, counts)
            except TimeoutError:
                if attempt == 0:
                    time.sleep(self.retry_delay)
                else:
                    return result("ERROR", "TOOL_TIMEOUT", attempts=2)
    except (OSError, ValueError, sqlite3.Error):
        return result("ERROR", "CONFIG_OR_STORAGE_UNAVAILABLE")
    return result("ERROR", "UNEXPECTED_STOP")

def get_environment_status(self, tenant_id: str, user_id: str) -> dict:
    return self._run(
        tenant_id, user_id,
        lambda role, counts: result(
            "OK", "ENVIRONMENT_READY", role=role,
            resources={name: {"configured": True, "count": count} for name, count in counts.items()},
        ),
    )

def check_case_prerequisites(self, tenant_id: str, user_id: str) -> dict:
    return self._run(
        tenant_id, user_id,
        lambda role, counts: result("BLOCKED", "FORBIDDEN") if role != "staff" else
        result("BLOCKED", "MISSING_CASE_AND_MATERIALS", missing=["case", "materials", "evidence"]),
    )

"""Small role boundary with explicit tool capabilities and empty provider slots."""
import json
from pathlib import Path


CAPABILITIES = {
    "query_controller": {"plan_query", "compose_answer"},
    "retriever": {"retrieve_registered_evidence"},
    "query_verifier": {"verify_conditions"},
    "update_controller": {"plan_update", "finish_run"},
    "extractor": {"submit_candidates"},
    "update_verifier": {"validate_candidates"},
    "jev": {"classify_changes", "check_support"},
}


class OfflineRoles:
    """Actually dispatch callables serially. They are not LLM/Nexent agents.

    A provider adapter must be implemented and independently validated before
    enabling model calls; merely filling an endpoint never silently enables it.
    """
    def __init__(self, config_path):
        config = json.loads(Path(config_path).read_text("utf-8"))
        if config["enabled"] or config["execution_mode"] != "offline_engineering_only":
            raise ValueError("LIVE_ADAPTER_NOT_ENABLED_IN_ENGINEERING_WORKFLOW")
        if any(any(value is not None for value in role.values()) for role in config["roles"].values()):
            raise ValueError("API_SLOTS_MUST_REMAIN_EMPTY")
        self.calls = []

    def invoke(self, role, tool, action, *, metadata=None):
        if tool not in CAPABILITIES.get(role, set()): raise ValueError("ROLE_TOOL_NOT_ALLOWED")
        self.calls.append({"role": role, "tool": tool, "remote_calls": 0, **(metadata or {})})
        if len(self.calls) > 2048: del self.calls[:1024]
        return action()

