def execute(name, run_id, tenant_id, user_id, action):
    try:
        scoped(run_id, tenant_id, user_id)
        value = result("OK", "MAINTENANCE_STAGE_COMPLETE", **action())
    except KBError as error:
        value = result("BLOCKED", str(error))
