def select_citations(catalog, version, selected_ids=None):
    """Select exact bound IDs only. Never accept replacement quotes or ranges."""
    indexed = {}
    for citation in catalog:
        if citation != bind_citation(citation) or citation["knowledge_version"] != version:
            raise ValueError("Changed or cross-version citation")
        key = citation["citation_id"]
        if key in indexed:
            raise ValueError("Duplicate catalog citation")
        indexed[key] = citation
    ids = list(indexed) if selected_ids is None else selected_ids
    if not isinstance(ids, list) or any(not isinstance(key, str) for key in ids):
        raise ValueError("Citation IDs only")
    if len(set(ids)) != len(ids) or any(key not in indexed for key in ids):
        raise ValueError("Unknown or duplicate citation ID")
    return [dict(indexed[key], source_span=dict(indexed[key]["source_span"])) for key in ids]

def render_answer(value):
    """Format full original chunks with distinct publication/effect/query dates."""
    if value["status"] != "OK":
        if value["citations"] or value["items"]:
            raise ValueError("Stopped answer must not contain evidence")
        return STOP_MESSAGES.get(value["message_code"], "当前无法提供已核对的办理依据。")
    citations = select_citations(value["citations"], value["knowledge_version"])
    if not citations or value["message_code"] != "EVIDENCE_FOUND":
        raise ValueError("Supporting evidence required")
    data = value["data"]
    lines = ["工作人员核对依据" if data["role"] == "staff" else "办事咨询依据",
             "以下为检索命中的完整原文片段；材料组合及办理结论须结合各条适用条件核对。",
             "知识库版本：" + value["knowledge_version"], "查询日期：" + data["query_date"]]
    if data["historical_snapshot"]:
        lines.append("历史知识库快照：不代表当前发布版本。")
    if data["query_view"] == "past":
        lines.append("历史日期筛选：按已核定的施行日期或服务信息截至日期筛选，不重建当时的网站状态。")
    elif data["query_view"] == "future":
        lines.append("未来日期筛选：仅按所选快照已知日期筛选，不保证未来仍然有效或服务不变。")
    for citation in citations:
        lines.extend(["", "引用：" + citation["citation_id"], "文件：" + citation["title"],
            "来源：" + citation["url"], "定位：" + citation["locator"],
            "发布日期：" + (citation["published_at"] or "未确认"),
            "生效日期：" + (citation["effective_from"] or "未确认"),
            "失效日期：" + (citation["effective_to"] or "未记录"),
            *(["服务信息截至日期：" + citation["information_as_of"], "该日期表示原文所载服务信息，不能据此推定施行日。"]
              if citation.get("date_basis") == "reported_service_information" else []),
            "原文：", citation["quote"]])
    lines.extend(["", "以上为依据检索结果，不构成审批决定。"])
    return "\n".join(lines)

def dormant_collector(db, config):
    return bool(config.get("attachment_only") and not db.execute("SELECT 1 FROM jobs WHERE site_id=?", (config["id"],)).fetchone()
                and not db.execute("SELECT 1 FROM documents WHERE site_id=?", (config["id"],)).fetchone())

def dependencies(db, roots):
    result = set()
    for source_id in roots:
        row = db.execute("SELECT config FROM sites WHERE id=?", (source_id,)).fetchone()
        if row:
            discovery = json.loads(row[0]).get("attachment_discovery", {})
            result.update(discovery.get("sources", []))
            result.update(owner["source_id"] for owner in discovery.get("owners", {}).values())
    return result

def attachment_status(db):
    if not db.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='attachment_edges'").fetchone():
        return []
    return [{"source_id": row["site_id"], "parent_url": row["url"], "statuses": json.loads(row["statuses"]),
             "active_jobs": db.execute("SELECT COUNT(DISTINCT j.id) FROM attachment_edges e JOIN jobs j ON j.site_id=e.target_site_id AND j.url=e.target_url WHERE e.parent_document_id=? AND j.state IN ('queued','running')", (row["document_id"],)).fetchone()[0],
             "failed_jobs": db.execute("SELECT COUNT(DISTINCT j.id) FROM attachment_edges e JOIN jobs j ON j.site_id=e.target_site_id AND j.url=e.target_url WHERE e.parent_document_id=? AND j.state='failed'", (row["document_id"],)).fetchone()[0]}
            for row in db.execute("SELECT d.id AS document_id,d.site_id,d.url,json_group_object(a.status,a.total) AS statuses FROM (SELECT parent_document_id,status,COUNT(*) AS total FROM attachment_edges GROUP BY parent_document_id,status) a JOIN documents d ON d.id=a.parent_document_id GROUP BY d.id ORDER BY d.site_id,d.url")]

"""Complete data bundles: online SQLite snapshot, referenced originals and non-auth configuration."""

import hashlib
import json
import re
import shutil
import sqlite3
from datetime import datetime, timezone
from pathlib import Path, PurePosixPath

from gov_mcp.knowledge import KnowledgeStore, encode


CONFIG_FILES = {"phase.json", "scope-regions.json", "knowledge-scope.json", "publication-policy.json", "sources.json"}
MAX_FILES, MAX_TOTAL_BYTES = 100000, 2 * 1024**3


def file_digest(path):
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024*1024), b""):
            digest.update(block)
    return digest.hexdigest()


def checked_path(root, name):
    if not isinstance(name, str) or "\\" in name or ":" in name:
        raise ValueError("Invalid bundle file path")
    parts = PurePosixPath(name)
    if parts.is_absolute() or any(p in (".", "..") for p in parts.parts) or not parts.parts or str(parts) != name:
        raise ValueError("Invalid bundle file path")
    if name not in CONFIG_FILES | {"knowledge.sqlite3"} and not re.fullmatch(r"originals/([0-9a-f]{2})/([0-9a-f]{64})", name):
        raise ValueError("Unrecognized bundle file")
    path = root.joinpath(*parts.parts)
    for candidate in (path, *path.parents):
        if candidate == root.parent:
            break
        if candidate.is_symlink():
            raise ValueError("Symlinks are not accepted in a bundle")
    if not path.resolve().is_relative_to(root.resolve()):
        raise ValueError("Bundle path escapes root")
    return path


def database_manifest(path):
    with sqlite3.connect(path.resolve().as_uri()+"?mode=ro", uri=True) as db:
        db.execute("PRAGMA trusted_schema=OFF")
        if db.execute("PRAGMA quick_check").fetchone()[0] != "ok" or db.execute("PRAGMA foreign_key_check").fetchone():
            raise ValueError("Snapshot database integrity check failed")
        originals = [row[0] for row in db.execute("SELECT DISTINCT sha256 FROM revisions ORDER BY sha256")]
        if any(not isinstance(sha, str) or not re.fullmatch("[0-9a-f]{64}", sha) for sha in originals):
            raise ValueError("Invalid original fingerprint in snapshot")
        sources = [json.loads(r[0]) for r in db.execute("SELECT config FROM sites ORDER BY id")]
        counts = {table: db.execute(f"SELECT COUNT(*) FROM {table}").fetchone()[0]
                  for table in ("documents", "revisions", "chunks", "versions", "heads")}
    return originals, sources, counts


def create_bundle(store, target):
    target = Path(target).resolve()
    if target.exists() or target == store.root or target.is_relative_to(store.root) and target.relative_to(store.root).parts[0] != "backups":
        raise ValueError("Use a new backup directory, outside live data or beneath backups/")
    target.mkdir(parents=True, exist_ok=False)
    config_before = {name: (store.root / name).read_bytes() for name in CONFIG_FILES - {"sources.json"} if (store.root / name).is_file()}
    database = target / "knowledge.sqlite3"
    with store.db() as source, sqlite3.connect(database) as destination:
        source.backup(destination)
    originals, sources, counts = database_manifest(database)
    files = ["knowledge.sqlite3"]
    for name in sorted(config_before):
        source = store.root / name
        if source.is_file():
            if source.is_symlink():
                raise ValueError("Configuration symlinks cannot be backed up")
            (target / name).write_bytes(config_before[name])
            files.append(name)
    if not {"phase.json", "publication-policy.json"} <= set(files):
        raise ValueError("Runtime marker and publication policy are required")
    (target / "sources.json").write_text(encode({"sources": sources}), encoding="utf-8")
    files.append("sources.json")
    for sha in originals:
        name = "originals/"+sha[:2]+"/"+sha
        source = checked_path(store.root, name)
        if file_digest(source) != sha:
            raise ValueError("Live original fingerprint mismatch")
        destination = checked_path(target, name)
        destination.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(source, destination)
        if file_digest(destination) != sha:
            raise ValueError("Copied original fingerprint mismatch")
        files.append(name)
    inventory = {name: {"sha256": file_digest(checked_path(target, name)), "size": checked_path(target, name).stat().st_size} for name in sorted(files)}
    config_after = {name: (store.root / name).read_bytes() for name in CONFIG_FILES - {"sources.json"} if (store.root / name).is_file()}
    if config_before != config_after:
        raise ValueError("Configuration changed during backup; retry into another new directory")
    manifest = {"schema": 1, "kind": "knowledge_data_backup", "complete": True,
        "created_at": datetime.now(timezone.utc).isoformat(), "files": inventory, "counts": counts,
        "referenced_originals": len(originals), "auth_credentials_included": False,
        "excluded": "MCP tokens, identity mappings, accounts, logs, process state, caches and unreferenced temporary originals",
        "restore_requirement": "Restore into a new isolated directory. Re-provision private service credentials separately."}
    (target / "manifest.json").write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding="utf-8")
    return {"directory": str(target), "manifest_sha256": file_digest(target / "manifest.json"),
            "files": len(files), "referenced_originals": len(originals), "counts": counts, "auth_credentials_included": False}


def restore_bundle(source, target):
    source, target = Path(source).resolve(), Path(target).resolve()
    if target.exists() or source == target or target.is_relative_to(source) or source.is_relative_to(target):
        raise ValueError("Restore target must be a new isolated directory")
    manifest = json.loads((source / "manifest.json").read_text(encoding="utf-8"))
    if manifest.get("schema") != 1 or manifest.get("kind") != "knowledge_data_backup" or manifest.get("complete") is not True:
        raise ValueError("Completed recognized backup required")
    inventory = manifest.get("files")
    if not isinstance(inventory, dict) or not {"phase.json", "knowledge.sqlite3", "publication-policy.json", "sources.json"} <= inventory.keys() or len(inventory) > MAX_FILES:
        raise ValueError("Incomplete or oversized bundle inventory")
    total = 0
    for name, expected in inventory.items():
        path = checked_path(source, name)
        if not isinstance(expected, dict) or type(expected.get("size")) is not int or expected["size"] < 0:
            raise ValueError("Invalid bundle file size")
        total += expected["size"]
        if total > MAX_TOTAL_BYTES or not path.is_file() or path.stat().st_size != expected["size"] or file_digest(path) != expected.get("sha256"):
            raise ValueError("Missing, changed or oversized bundle file")
    originals, _, counts = database_manifest(source / "knowledge.sqlite3")
    if any("originals/"+sha[:2]+"/"+sha not in inventory for sha in originals):
        raise ValueError("Bundle omits a referenced original")
    if any(file_digest(checked_path(source, "originals/"+sha[:2]+"/"+sha)) != sha for sha in originals):
        raise ValueError("Original content does not match the database fingerprint")
    marker = json.loads((source / "phase.json").read_text(encoding="utf-8"))
    if marker != {"phase": "knowledge_update", "schema_version": 1}:
        raise ValueError("Dedicated knowledge update marker required")
    snapshot = KnowledgeStore(source, read_only=True)
    with snapshot.db() as db:
        for revision in db.execute("SELECT id FROM revisions"):
            snapshot._verify(db, revision[0], require_review=False)
        for version in db.execute("SELECT members FROM versions WHERE state='published'"):
            for member in json.loads(version[0]):
                snapshot._verify(db, member)
    target.mkdir(parents=True, exist_ok=False)
    # The marker is copied last so a partially restored directory cannot be mistaken for ready.
    for name in sorted(inventory, key=lambda value: value == "phase.json"):
        original, restored = checked_path(source, name), checked_path(target, name)
        restored.parent.mkdir(parents=True, exist_ok=True)
        with original.open("rb") as input_stream, restored.open("xb") as output_stream:
            shutil.copyfileobj(input_stream, output_stream)
        if file_digest(restored) != inventory[name]["sha256"]:
            raise ValueError("Restore copy fingerprint mismatch")
    restored_store = KnowledgeStore(target)
    # Never advertise backed-up workers as currently alive. This does not start any process.
    with restored_store.db() as db:
        db.execute("UPDATE workers SET progress='completed'")
        restored_store.log(db, "data_bundle_restored", {"manifest_sha256": file_digest(source / "manifest.json")})
    result = {"restored_to": str(target), "counts": counts, "referenced_originals": len(originals),
              "services_started": False, "credentials_must_be_reprovisioned": True,
              "source_manifest_sha256": file_digest(source / "manifest.json")}
    (target / "restore-report.json").write_text(json.dumps(result, ensure_ascii=False, indent=2), encoding="utf-8")
    return result

def file_digest(path):
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024*1024), b""):
            digest.update(block)
    return digest.hexdigest()

def checked_path(root, name):
    if not isinstance(name, str) or "\\" in name or ":" in name:
        raise ValueError("Invalid bundle file path")
    parts = PurePosixPath(name)
    if parts.is_absolute() or any(p in (".", "..") for p in parts.parts) or not parts.parts or str(parts) != name:
        raise ValueError("Invalid bundle file path")
    if name not in CONFIG_FILES | {"knowledge.sqlite3"} and not re.fullmatch(r"originals/([0-9a-f]{2})/([0-9a-f]{64})", name):
        raise ValueError("Unrecognized bundle file")
    path = root.joinpath(*parts.parts)
    for candidate in (path, *path.parents):
        if candidate == root.parent:
            break
        if candidate.is_symlink():
            raise ValueError("Symlinks are not accepted in a bundle")
    if not path.resolve().is_relative_to(root.resolve()):
        raise ValueError("Bundle path escapes root")
    return path

def database_manifest(path):
    with sqlite3.connect(path.resolve().as_uri()+"?mode=ro", uri=True) as db:
        db.execute("PRAGMA trusted_schema=OFF")
        if db.execute("PRAGMA quick_check").fetchone()[0] != "ok" or db.execute("PRAGMA foreign_key_check").fetchone():
            raise ValueError("Snapshot database integrity check failed")
        originals = [row[0] for row in db.execute("SELECT DISTINCT sha256 FROM revisions ORDER BY sha256")]
        if any(not isinstance(sha, str) or not re.fullmatch("[0-9a-f]{64}", sha) for sha in originals):
            raise ValueError("Invalid original fingerprint in snapshot")
        sources = [json.loads(r[0]) for r in db.execute("SELECT config FROM sites ORDER BY id")]
        counts = {table: db.execute(f"SELECT COUNT(*) FROM {table}").fetchone()[0]
                  for table in ("documents", "revisions", "chunks", "versions", "heads")}
    return originals, sources, counts

def create_bundle(store, target):
    target = Path(target).resolve()
    if target.exists() or target == store.root or target.is_relative_to(store.root) and target.relative_to(store.root).parts[0] != "backups":
        raise ValueError("Use a new backup directory, outside live data or beneath backups/")
    target.mkdir(parents=True, exist_ok=False)
    config_before = {name: (store.root / name).read_bytes() for name in CONFIG_FILES - {"sources.json"} if (store.root / name).is_file()}
    database = target / "knowledge.sqlite3"
    with store.db() as source, sqlite3.connect(database) as destination:
        source.backup(destination)
    originals, sources, counts = database_manifest(database)
    files = ["knowledge.sqlite3"]
    for name in sorted(config_before):
        source = store.root / name
        if source.is_file():
            if source.is_symlink():
                raise ValueError("Configuration symlinks cannot be backed up")
            (target / name).write_bytes(config_before[name])
            files.append(name)
    if not {"phase.json", "publication-policy.json"} <= set(files):
        raise ValueError("Runtime marker and publication policy are required")
    (target / "sources.json").write_text(encode({"sources": sources}), encoding="utf-8")
    files.append("sources.json")
    for sha in originals:
        name = "originals/"+sha[:2]+"/"+sha
        source = checked_path(store.root, name)
        if file_digest(source) != sha:
            raise ValueError("Live original fingerprint mismatch")
        destination = checked_path(target, name)
        destination.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(source, destination)
        if file_digest(destination) != sha:
            raise ValueError("Copied original fingerprint mismatch")
        files.append(name)
    inventory = {name: {"sha256": file_digest(checked_path(target, name)), "size": checked_path(target, name).stat().st_size} for name in sorted(files)}
    config_after = {name: (store.root / name).read_bytes() for name in CONFIG_FILES - {"sources.json"} if (store.root / name).is_file()}
    if config_before != config_after:
        raise ValueError("Configuration changed during backup; retry into another new directory")
    manifest = {"schema": 1, "kind": "knowledge_data_backup", "complete": True,
        "created_at": datetime.now(timezone.utc).isoformat(), "files": inventory, "counts": counts,
        "referenced_originals": len(originals), "auth_credentials_included": False,
        "excluded": "MCP tokens, identity mappings, accounts, logs, process state, caches and unreferenced temporary originals",
        "restore_requirement": "Restore into a new isolated directory. Re-provision private service credentials separately."}
    (target / "manifest.json").write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding="utf-8")
    return {"directory": str(target), "manifest_sha256": file_digest(target / "manifest.json"),
            "files": len(files), "referenced_originals": len(originals), "counts": counts, "auth_credentials_included": False}

def restore_bundle(source, target):
    source, target = Path(source).resolve(), Path(target).resolve()
    if target.exists() or source == target or target.is_relative_to(source) or source.is_relative_to(target):
        raise ValueError("Restore target must be a new isolated directory")
    manifest = json.loads((source / "manifest.json").read_text(encoding="utf-8"))
    if manifest.get("schema") != 1 or manifest.get("kind") != "knowledge_data_backup" or manifest.get("complete") is not True:
        raise ValueError("Completed recognized backup required")
    inventory = manifest.get("files")
    if not isinstance(inventory, dict) or not {"phase.json", "knowledge.sqlite3", "publication-policy.json", "sources.json"} <= inventory.keys() or len(inventory) > MAX_FILES:
        raise ValueError("Incomplete or oversized bundle inventory")
    total = 0
    for name, expected in inventory.items():
        path = checked_path(source, name)
        if not isinstance(expected, dict) or type(expected.get("size")) is not int or expected["size"] < 0:
            raise ValueError("Invalid bundle file size")
        total += expected["size"]
        if total > MAX_TOTAL_BYTES or not path.is_file() or path.stat().st_size != expected["size"] or file_digest(path) != expected.get("sha256"):
            raise ValueError("Missing, changed or oversized bundle file")
    originals, _, counts = database_manifest(source / "knowledge.sqlite3")
    if any("originals/"+sha[:2]+"/"+sha not in inventory for sha in originals):
        raise ValueError("Bundle omits a referenced original")
    if any(file_digest(checked_path(source, "originals/"+sha[:2]+"/"+sha)) != sha for sha in originals):
        raise ValueError("Original content does not match the database fingerprint")
    marker = json.loads((source / "phase.json").read_text(encoding="utf-8"))
    if marker != {"phase": "knowledge_update", "schema_version": 1}:
        raise ValueError("Dedicated knowledge update marker required")
    snapshot = KnowledgeStore(source, read_only=True)
    with snapshot.db() as db:
        for revision in db.execute("SELECT id FROM revisions"):
            snapshot._verify(db, revision[0], require_review=False)
        for version in db.execute("SELECT members FROM versions WHERE state='published'"):
            for member in json.loads(version[0]):
                snapshot._verify(db, member)
    target.mkdir(parents=True, exist_ok=False)
    # The marker is copied last so a partially restored directory cannot be mistaken for ready.
    for name in sorted(inventory, key=lambda value: value == "phase.json"):
        original, restored = checked_path(source, name), checked_path(target, name)
        restored.parent.mkdir(parents=True, exist_ok=True)
        with original.open("rb") as input_stream, restored.open("xb") as output_stream:
            shutil.copyfileobj(input_stream, output_stream)
        if file_digest(restored) != inventory[name]["sha256"]:
            raise ValueError("Restore copy fingerprint mismatch")
    restored_store = KnowledgeStore(target)
    # Never advertise backed-up workers as currently alive. This does not start any process.
    with restored_store.db() as db:
        db.execute("UPDATE workers SET progress='completed'")
        restored_store.log(db, "data_bundle_restored", {"manifest_sha256": file_digest(source / "manifest.json")})
    result = {"restored_to": str(target), "counts": counts, "referenced_originals": len(originals),
              "services_started": False, "credentials_must_be_reprovisioned": True,
              "source_manifest_sha256": file_digest(source / "manifest.json")}
    (target / "restore-report.json").write_text(json.dumps(result, ensure_ascii=False, indent=2), encoding="utf-8")
    return result

def suggest(chunks, metadata):
    sections = []
    for chunk in chunks:
        text = chunk["text"]
        topics = [{"code": code, "label": label, "matched_terms": [term for term in terms if term in text]}
                  for code, label, terms in TOPICS if any(term in text for term in terms)]
        branches = [{"code": code, "label": label, "matched_terms": [term for term in terms if term in text]}
                    for code, label, terms in BRANCHES if any(term in text for term in terms)]
        instruction_flag = any(term in text for term in ("忽略系统规则", "忽略之前的指令", "自动发布所有", "ignore previous instructions"))
        sections.append({"locator": chunk["locator"], "topics": topics, "mentioned_branches": branches,
                         "instruction_like_text_requires_review": instruction_flag,
                         "source_structure": structure(text),
                         "material_requirement_relationship": "unknown_pending_human_review"})
    return {"taxonomy_version": VERSION, "status": "machine_proposal_not_approved",
        "scope_from_source_config_not_inferred_from_host": {"region": metadata["region"], "matter": metadata["matter"]},
        "topic_codes": sorted({topic["code"] for section in sections for topic in section["topics"]}),
        "mixed_branch_mentions": len({branch["code"] for section in sections for branch in section["mentioned_branches"]}) > 1,
        "sections": sections,
        "retrieval_units": propose_units(chunks),
        "warning": "Mentions and keyword matches do not establish applicability, required materials, current effectivity or a review decision"}

def citation_date_fields(metadata):
    basis = metadata.get("date_basis")
    return {"date_basis": SERVICE_KIND, "information_as_of": basis["information_as_of"]} if basis else {}

def demo_store(runtime):
    root = Path(runtime).resolve()
    marker = read_json(root / "team-demo.json")
    if marker.get("mode") != MODE or read_json(root / "publication-policy.json") != POLICY:
        raise ValueError("该目录不是独立的虚构演示库，拒绝操作。")
    store = KnowledgeStore(root)
    with store.db() as db:
        sources = {r[0] for r in db.execute("SELECT id FROM sites")}
        if sources != {SOURCE}:
            raise ValueError("演示目录包含其他来源，拒绝操作。")
        for row in db.execute("SELECT metadata FROM revisions"):
            metadata = json.loads(row[0])
            if (metadata.get("document_type"), metadata.get("region"), metadata.get("matter")) != ("synthetic", REGION, MATTER):
                raise ValueError("演示目录混入了非演示资料，拒绝操作。")
    return store, marker

def query(runtime, role, question=QUESTION, version=None):
    store, marker = demo_store(runtime)
    if role not in ("citizen", "staff"):
        raise ValueError("演示角色只能选择 citizen 或 staff。")
    if version and version not in {v["version"] for v in marker["versions"]}:
        raise ValueError("只能查询当前演示库中的已发布演示版本。")
    result = KnowledgeTools(store.root).execute("search_evidence", "team-demo", role,
                                               query=question, knowledge_version=version)
    return {"demo": True, "warning": WARNING, "result": result}

def refresh(runtime):
    store, marker = demo_store(runtime)
    with store.db() as db:
        for entry in marker["versions"]:
            store._verify(db, entry["revision"])
    revision = ingest_fixture(store, marker["versions"][-1]["number"])
    if revision != marker["versions"][-1]["revision"]:
        raise ValueError("演示资料与版本记录不一致，拒绝沿用检查结果。")
    return check(store.root)

def create_app(runtime):
    from starlette.applications import Starlette
    from starlette.middleware import Middleware
    from starlette.middleware.trustedhost import TrustedHostMiddleware
    from starlette.responses import HTMLResponse, JSONResponse, Response
    from starlette.routing import Route

    store, marker = demo_store(runtime)

    async def home(request):
        return HTMLResponse((Path(__file__).parent / "knowledge_demo.html").read_text(encoding="utf-8"),
            headers={"Content-Security-Policy": "default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; frame-ancestors 'none'", "X-Content-Type-Options": "nosniff"})

    async def health(request):
        return JSONResponse({"mode": MODE, "warning": WARNING, "status": "UP"})

    async def favicon(request):
        return Response(status_code=204)

    async def search(request):
        try:
            return JSONResponse(query(store.root, request.query_params.get("role", "citizen"),
                request.query_params.get("q", QUESTION), request.query_params.get("version")))
        except (ValueError, OSError) as error:
            return JSONResponse({"demo": True, "warning": WARNING, "error": str(error)}, status_code=400)

    async def status(request):
        _, current = demo_store(store.root)
        return JSONResponse({"demo": True, "warning": WARNING, "counts": store.status()["counts"], "versions": current["versions"]})

    return Starlette(routes=[Route("/", home), Route("/favicon.ico", favicon), Route("/health", health), Route("/api/query", search), Route("/api/status", status)],
        middleware=[Middleware(TrustedHostMiddleware, allowed_hosts=["127.0.0.1", "localhost", "testserver"])])

