def observe_html(raw, selectors=None, *, content_selector=None, excluded_selectors=None):
    text = raw.decode("utf-8", errors="strict")
    parser = PageSignals()
    parser.feed(text)
    fields = parser.fields
    if content_selector:
        body = ArticleParser(content_selector, excluded_selectors)
        body.feed(text)
        attachments = sorted({href for href in body.selected_links
                              if urlsplit(href).path.lower().endswith((".pdf", ".doc", ".docx", ".xls", ".xlsx", ".txt", ".csv", ".zip", ".ofd", ".wps"))})
        if len(attachments) > 100 or any(len(href) > 2048 for href in attachments):
            raise ValueError("Oversized body attachment metadata")
        if attachments:
            fields["body:document_links"] = attachments
            fields["body:document_link_titles"] = sorted({encode({"url": link["url"], "title": link["title"][:300]})
                                                          for link in body.selected_link_records if link["url"] in attachments})
    for name, selector in (selectors or {}).items():
        block = ArticleParser(selector)
        block.feed(text)
        # An empty observation is significant too: a removed validity/date block needs review.
        fields["block:" + name] = ["".join(block.parts)]
    normalized = {key: sorted({re.sub(r"\s+", " ", value).strip() for value in values})
                  for key, values in sorted(fields.items())}
    if len(encode(normalized)) > 32768 or any(len(value) > 8000 for values in normalized.values() for value in values):
        raise ValueError("Oversized page metadata; requires a narrower selector")
    return {"schema": 1, "media_type": "text/html", "fields": normalized}

class IndexLinks(HTMLParser):
    def __init__(self):
        super().__init__()
        self.current, self.links = None, []

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag == "a" and attrs.get("href"):
            self.current = [attrs["href"], [], attrs.get("title", "")]

    def handle_data(self, text):
        if self.current:
            self.current[1].append(text)

    def handle_endtag(self, tag):
        if tag == "a" and self.current:
            self.links.append((self.current[0], re.sub(r"\s+", " ", "".join(self.current[1]) or self.current[2]).strip()))
            self.current = None

