param([ValidateSet('general','mainland')][string]$RegistryProfile = 'general', [switch]$ProvisionAccounts, [switch]$BuildMinioFromSource)
$ErrorActionPreference = 'Stop'
$TaskRoot = Split-Path -Parent $PSScriptRoot
Set-Location -LiteralPath $TaskRoot
$Python = Join-Path $TaskRoot '.venv/Scripts/python.exe'
$Git = (Get-Command git -ErrorAction Stop).Source
$Bash = Join-Path (Split-Path (Split-Path $Git -Parent) -Parent) 'bin/bash.exe'
if (-not (Test-Path -LiteralPath $Bash)) { throw 'Git for Windows Bash was not found beside git.exe.' }
$DockerCandidates = @("$env:LOCALAPPDATA/Programs/DockerDesktop/resources/bin/docker.exe", 'C:/Program Files/Docker/Docker/resources/bin/docker.exe')
$Docker = $DockerCandidates | Where-Object { Test-Path -LiteralPath $_ } | Select-Object -First 1
if (-not $Docker) { throw 'Docker Desktop is not installed. Install it after enabling WSL 2.' }
& $Python scripts/check_docker.py $Docker
if ($LASTEXITCODE -ne 0) { throw 'Docker engine is unavailable. WSL 2 and Docker Desktop must be running.' }
$env:PATH = "$(Split-Path -Parent $Docker);$env:PATH"
$PinnedCommit = & $Git -C vendor/nexent rev-parse HEAD
if ($PinnedCommit -ne '519b9b17c7f4cbc623256ac318ea96a20f33772e') { throw 'Nexent checkout does not match the pinned v2.7.0 commit.' }
& $Python scripts/prepare_runtime.py
if ($LASTEXITCODE -ne 0) { throw 'Runtime preparation failed.' }
& $Python scripts/prepare_deploy.py
if ($LASTEXITCODE -ne 0) { throw 'Deployment preparation failed.' }
if ($BuildMinioFromSource) {
    & (Join-Path $PSScriptRoot 'build_minio.ps1')
    if ($LASTEXITCODE -ne 0) { throw 'Pinned MinIO source build failed.' }
    & $Python scripts/prepare_deploy.py --use-source-minio
    if ($LASTEXITCODE -ne 0) { throw 'Pinned MinIO image configuration failed.' }
}
$DataRoot = (Join-Path $TaskRoot '.runtime/nexent-data').Replace('\','/')
$DataRoot = '/' + $DataRoot.Substring(0,1).ToLower() + $DataRoot.Substring(2)
Push-Location vendor/nexent
try {
    # Windows PowerShell treats native stderr as errors, including normal
    # Compose progress. Capture output and use the native exit code instead.
    $PreviousErrorActionPreference = $ErrorActionPreference
    try {
        $ErrorActionPreference = 'Continue'
        & $Bash deploy/docker/.services-only.sh --version v2.7.0 --components infrastructure,application,supabase --port-policy development --image-source $RegistryProfile --sandbox-mode lightweight --root-dir $DataRoot *> (Join-Path $TaskRoot '.runtime/nexent-deploy.log')
        $DeployExitCode = $LASTEXITCODE
    } finally { $ErrorActionPreference = $PreviousErrorActionPreference }
    if ($DeployExitCode -ne 0) { throw 'Official Nexent deployment failed; inspect the private .runtime/nexent-deploy.log.' }
} finally { Pop-Location }
& $Docker compose -f compose.mcp.yml up -d --build
if ($LASTEXITCODE -ne 0) { throw 'MCP container startup failed.' }
& $Python scripts/runtime_sandbox.py
if ($LASTEXITCODE -ne 0) { throw 'Runtime sandbox recovery failed.' }
& $Python scripts/check_native_ready.py --wait-seconds 120
if ($LASTEXITCODE -ne 0) { throw 'Native service or container-to-Ollama readiness failed. No account login was attempted.' }
if ($ProvisionAccounts) {
    & (Join-Path $PSScriptRoot 'initialize_accounts.ps1')
    if ($LASTEXITCODE -ne 0) { throw 'Native provisioning failed; no acceptance claim can be made.' }
} else {
    Write-Output 'Services are ready. Account signup/login is the next user-operated step.'
    Write-Output 'Run powershell -ExecutionPolicy Bypass -File scripts\initialize_accounts.ps1 yourself when ready, then sign in at http://127.0.0.1:3000 for native UI checks.'
}

param([switch]$CheckOnly)
$ErrorActionPreference = 'Stop'
$projectPath = [IO.Path]::GetFullPath((Split-Path -Parent $PSScriptRoot))
$runtimePath = Join-Path $projectPath '.runtime\knowledge-update'
$statusPath = Join-Path $runtimePath 'startup-recovery-status.json'
$pausePath = Join-Path $runtimePath 'service-paused.json'
$utf8 = New-Object Text.UTF8Encoding($false)
$sha = [Security.Cryptography.SHA256]::Create()
try { $key = ([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($runtimePath)))).Replace('-', '').Substring(0, 16) }
finally { $sha.Dispose() }
$mutex = New-Object Threading.Mutex($false, ('Local\HuaweiICTKnowledgeUpdate-' + $key))
$locked = $false
$previous = $null

function Test-OwnedModule($candidate, [string]$module) {
    if (-not $candidate -or -not $candidate.CommandLine) { return $false }
    return ($candidate.CommandLine -match ('(?:^|\s)-m\s+' + [regex]::Escape($module) + '(?:\s|$)')) -and
        ($candidate.CommandLine.IndexOf($runtimePath, [StringComparison]::OrdinalIgnoreCase) -ge 0)
}

function Get-OwnedComponents {
    $found = @()
    foreach ($candidate in @(Get-CimInstance Win32_Process -Filter "Name='python.exe'")) {
        $owned = (Test-OwnedModule $candidate 'gov_mcp.knowledge_web') -or
                 (Test-OwnedModule $candidate 'gov_mcp.knowledge_server') -or
                 (Test-OwnedModule $candidate 'gov_mcp.knowledge_maintenance') -or
                 ((Test-OwnedModule $candidate 'gov_mcp.knowledge_cli') -and $candidate.CommandLine -match '\bworker\b' -and $candidate.CommandLine -match '--cycles\s+0(?:\s|$)')
        if ($owned) { $found += $candidate }
    }
    return $found
}

function Read-ServiceState {
    $statePath = Join-Path $runtimePath 'service-state.json'
    if (Test-Path -LiteralPath $statePath) { return Get-Content -LiteralPath $statePath -Raw -Encoding UTF8 | ConvertFrom-Json }
    return $null
}

function Get-OwnedSupervisor($state) {
    if (-not $state) { return $null }
    $candidate = Get-CimInstance Win32_Process -Filter ('ProcessId=' + [int]$state.supervisor_pid) -ErrorAction SilentlyContinue
    if (Test-OwnedModule $candidate 'gov_mcp.knowledge_service') { return $candidate }
    return $null
}

function Stop-VerifiedComponent($candidate) {
    $fresh = Get-CimInstance Win32_Process -Filter ('ProcessId=' + [int]$candidate.ProcessId) -ErrorAction SilentlyContinue
    if ($fresh -and $fresh.CreationDate -eq $candidate.CreationDate -and $fresh.CommandLine -eq $candidate.CommandLine) {
        Stop-Process -Id $fresh.ProcessId -ErrorAction SilentlyContinue
    }
}

function Test-Ready($state) {
    if (-not (Get-OwnedSupervisor $state)) { return $false }
    $age = ([DateTimeOffset]::UtcNow.ToUnixTimeSeconds()) - [double]$state.checked_at
    if ($age -gt 90) { return $false }
    foreach ($name in $state.processes.PSObject.Properties.Name) {
        $candidate = Get-CimInstance Win32_Process -Filter ('ProcessId=' + [int]$state.processes.$name) -ErrorAction SilentlyContinue
        $module = @{web='gov_mcp.knowledge_web'; worker='gov_mcp.knowledge_cli'; maintenance='gov_mcp.knowledge_maintenance'; mcp='gov_mcp.knowledge_server'}[$name]
        if (-not $module -or -not (Test-OwnedModule $candidate $module)) { return $false }
    }
    try {
        $value = Invoke-RestMethod -Uri 'http://127.0.0.1:8772/api/status' -TimeoutSec 5
        if ($value.mode -ne 'knowledge_update') { return $false }
        foreach ($identity in @('knowledge-worker', 'knowledge-maintenance')) {
            $worker = @($value.workers | Where-Object id -EQ $identity)
            if (-not $worker.Count -or $worker[0].stale) { return $false }
        }
        if ($state.processes.mcp) {
            $mcpHealth = Invoke-RestMethod -Uri 'http://127.0.0.1:8773/health' -TimeoutSec 5
            if ($mcpHealth.status -ne 'UP') { return $false }
        }
        # The venv launcher and the actual listener can have different PIDs.
        foreach ($port in @(8772) + $(if ($state.processes.mcp) { @(8773) } else { @() })) {
            $listeners = @(Get-NetTCPConnection -State Listen -ErrorAction Stop | Where-Object LocalPort -EQ $port)
            if (-not $listeners.Count) { return $false }
            foreach ($listener in $listeners) {
                $candidate = Get-CimInstance Win32_Process -Filter ('ProcessId=' + [int]$listener.OwningProcess)
                $module = if ($port -eq 8772) { 'gov_mcp.knowledge_web' } else { 'gov_mcp.knowledge_server' }
                if (-not (Test-OwnedModule $candidate $module)) { return $false }
            }
        }
    } catch { return $false }
    return $true
}

function Save-RecoveryStatus([string]$action, [bool]$ready, [string]$failure = $null) {
    $state = Read-ServiceState
    $count = if ($previous) { [int]$previous.recovery_count } else { 0 }
    if ($action -eq 'recovered') { $count++ }
    $lastRecoveredAt = if ($action -eq 'recovered') { [DateTimeOffset]::UtcNow.ToUnixTimeSeconds() } elseif ($previous.last_recovered_at) { $previous.last_recovered_at } elseif ($previous.action -eq 'recovered') { $previous.checked_at } else { $null }
    $lastRecoveredPid = if ($action -eq 'recovered') { $state.supervisor_pid } elseif ($previous.last_recovered_supervisor_pid) { $previous.last_recovered_supervisor_pid } elseif ($previous.action -eq 'recovered') { $previous.supervisor_pid } else { $null }
    $record = [ordered]@{ checked_at=[DateTimeOffset]::UtcNow.ToUnixTimeSeconds(); action=$action; ready=$ready;
        recovery_count=$count; last_recovered_at=$lastRecoveredAt; last_recovered_supervisor_pid=$lastRecoveredPid;
        supervisor_pid=$(if ($state) {$state.supervisor_pid} else {$null}); error=$failure;
        no_publication_performed=$true; mode='current_user_local_service_recovery' }
    $temporary = $statusPath + '.tmp'
    [IO.File]::WriteAllText($temporary, ($record | ConvertTo-Json -Depth 6), $utf8)
    Move-Item -LiteralPath $temporary -Destination $statusPath -Force
    if ($action -ne 'healthy' -and ($action -eq 'recovered' -or $previous.action -ne $action -or $previous.error -ne $failure)) {
        [IO.File]::AppendAllText((Join-Path $runtimePath 'startup-recovery-audit.jsonl'), (($record | ConvertTo-Json -Compress) + [Environment]::NewLine), $utf8)
    }
    return [pscustomobject]$record
}

try {
    $marker = Get-Content -LiteralPath (Join-Path $runtimePath 'phase.json') -Raw -Encoding UTF8 | ConvertFrom-Json
    if ($marker.phase -ne 'knowledge_update' -or $marker.schema_version -ne 1) { throw '运行目录标记不符，停止恢复。' }
    if (-not (Test-Path -LiteralPath (Join-Path $projectPath '.venv\Scripts\python.exe'))) { throw '项目Python环境不存在。' }
    try { $locked = $mutex.WaitOne(0) } catch [Threading.AbandonedMutexException] { $locked = $true }
    if (-not $locked) { Write-Output '已有本项目恢复检查正在运行。'; exit 0 }
    if (Test-Path -LiteralPath $statusPath) { $previous = Get-Content -LiteralPath $statusPath -Raw -Encoding UTF8 | ConvertFrom-Json }
    if (Test-Path -LiteralPath $pausePath) { Save-RecoveryStatus 'paused' $false; exit 0 }
    $state = Read-ServiceState
    if (Test-Ready $state) { Save-RecoveryStatus 'healthy' $true; exit 0 }
    if ($CheckOnly) { Save-RecoveryStatus 'check_failed' $false; exit 1 }
    $supervisor = Get-OwnedSupervisor $state
    if ($supervisor) {
        # Give the live supervisor a full component-repair tick before replacing it.
        Start-Sleep -Seconds 17
        $state = Read-ServiceState
        if (Test-Ready $state) { Save-RecoveryStatus 'healthy' $true; exit 0 }
        if (Test-Path -LiteralPath $pausePath) { Save-RecoveryStatus 'paused' $false; exit 0 }
        $supervisor = Get-OwnedSupervisor $state
        if ($supervisor) { Stop-VerifiedComponent $supervisor }
    }
    foreach ($candidate in @(Get-OwnedComponents)) { Stop-VerifiedComponent $candidate }
    Start-Sleep -Seconds 1
    foreach ($port in @(8772,8773)) {
        if (@(Get-NetTCPConnection -State Listen -ErrorAction Stop | Where-Object LocalPort -EQ $port).Count) {
            throw "端口 $port 仍被占用；不会停止未确认归属的程序。"
        }
    }
    if (Test-Path -LiteralPath $pausePath) { Save-RecoveryStatus 'paused' $false; exit 0 }
    & (Join-Path $PSScriptRoot 'start_knowledge_update.ps1') -FromRecovery | Out-Null
    $deadline = [DateTime]::UtcNow.AddSeconds(35)
    do {
        if (Test-Ready (Read-ServiceState)) { Save-RecoveryStatus 'recovered' $true; exit 0 }
        Start-Sleep -Seconds 2
    } while ([DateTime]::UtcNow -lt $deadline)
    throw '本项目恢复后尚未就绪，请检查私有运行日志。'
} catch {
    if ($locked -and (Test-Path -LiteralPath $runtimePath)) { Save-RecoveryStatus 'failed' $false $_.Exception.Message | Out-Null }
    Write-Error $_.Exception.Message
    exit 1
} finally {
    if ($locked) { $mutex.ReleaseMutex() }
    $mutex.Dispose()
}

async (page) => {
  const trace = [];
  for (const [name, path, filename] of [
    ['准备空更新', '/api/tools/prepare_update', 'output/playwright/m1-BT11-prepare.png'],
    ['检查发布前提', '/api/tools/publish_update', 'output/playwright/m1-BT11-publish.png']
  ]) {
    const pending = page.waitForResponse(response => new URL(response.url()).pathname === path && response.request().method() === 'POST');
    await page.getByRole('button', {name, exact:true}).click();
    const response = await pending;
    const value = await response.json();
    await page.getByRole('status').filter({hasText:'BLOCKED / FORBIDDEN'}).waitFor();
    await page.screenshot({path:filename,scale:'css'});
    trace.push({operation:path, http_status:response.status(),result:value,screenshot:filename});
  }
  return {passed:trace.every(r=>r.result.status==='BLOCKED' && r.result.message_code==='FORBIDDEN' && r.result.data.role==='citizen'), trace};
}

async (page) => {
  await page.getByRole('button', {name:'执行',exact:true}).click();
  await page.getByRole('textbox', {name:'发送消息...',exact:true}).fill('空白技术验收：按真实群众身份检索空知识库，保留完整工具结果并停止。');
  await page.getByRole('button', {name:'发送',exact:true}).click();
}

async (page) => {
  let agentRuns = 0;
  const count = request => { if (request.method() === 'POST' && new URL(request.url()).pathname === '/api/agent/run') agentRuns++; };
  page.on('request', count);
  try {
    await page.getByRole('button', { name: '执行', exact: true }).click();
    const input = page.getByRole('textbox', { name: '发送消息...', exact: true });
    const send = page.getByRole('button', { name: '发送', exact: true });
    await input.fill('');
    const emptyDisabled = await send.isDisabled();
    await input.press('Enter');
    await input.fill(' \n\t');
    const whitespaceDisabled = await send.isDisabled();
    await input.press('Enter');
    await input.fill('');
    await page.waitForTimeout(800);
    await page.screenshot({path:'output/playwright/m1-BT02.png',scale:'css'});
    return {empty_disabled:emptyDisabled, whitespace_disabled:whitespaceDisabled,
      agent_run_requests_before:0, agent_run_requests_after:agentRuns,
      model_dispatch_count:agentRuns, assertion:emptyDisabled && whitespaceDisabled && agentRuns===0};
  } finally { page.removeListener('request', count); }
}

async (page) => {
  const pending = page.waitForResponse(response => new URL(response.url()).pathname === '/api/state');
  await page.getByRole('button', {name:'刷新状态',exact:true}).click();
  const response = await pending;
  const value = await response.json();
  await page.getByRole('status').filter({hasText:'ERROR / '+value.message_code}).waitFor();
  const screenshot = 'output/playwright/m1-BT12-'+value.message_code+'.png';
  await page.screenshot({path:screenshot,scale:'css'});
  return {http_status:response.status(), result:value, screenshot,
    role_text:await page.getByText('已核定业务角色：群众',{exact:true}).textContent()};
}

async (page) => {
  await page.getByRole('button', {name:'执行',exact:true}).click();
  await page.getByRole('textbox', {name:'发送消息...',exact:true}).fill('空白技术异常验收：按真实身份检查环境，ERROR 后立即停止，不调用子 Agent 或业务工具。');
  const pending = page.waitForResponse(response => new URL(response.url()).pathname === '/api/agent/run' && response.request().method() === 'POST');
  await page.getByRole('button', {name:'发送',exact:true}).click();
  const response = await pending;
  const raw = (await response.body()).toString('utf8');
  if(response.status()!==200){
    let error={};try{error=JSON.parse(raw)}catch{}
    return {http_status:response.status(),error_code:error.code,error_detail:error.detail,
      request_header_names:Object.keys(response.request().headers()),body_keys:Object.keys(response.request().postDataJSON())};
  }
  const events = raw.split('\n').filter(line=>line.startsWith('data:') && line.slice(5).trim()).map(line=>JSON.parse(line.slice(5).trim()));
  const finals = events.filter(e=>e.type==='final_answer' && !e.depth).map(e=>e.content);
  const value = finals.length===1 && typeof finals[0]==='object' ? finals[0] : JSON.parse(finals.join(''));
  await page.getByText(JSON.stringify(value)).first().waitFor().catch(async()=>{
    await page.getByText(new RegExp('"message_code".*'+value.message_code)).first().waitFor();
  });
  const idHeader = response.headers()['conversation_id'];
  const created = events.find(e=>e.type==='conversation_created');
  let createdId = null;
  if(created){try{createdId=typeof created.content==='object'?created.content.conversation_id:JSON.parse(created.content).conversation_id;}catch{}}
  const requestId = response.request().postDataJSON().conversation_id;
  const conversationId = idHeader && /^\d+$/.test(idHeader)?Number(idHeader):(createdId || (Number.isInteger(requestId)&&requestId>0?requestId:null));
  const screenshot = 'output/playwright/m1-native-'+value.message_code+'.png';
  await page.screenshot({path:screenshot,scale:'css'});
  return {http_status:response.status(),conversation_id:conversationId,events,result:value,screenshot};
}

async (page) => {
