            if ($taskHealth.status -eq 'UP') { $taskReady = $true; break }
        } catch { }
        Start-Sleep -Seconds 1
    }
    if (-not $taskReady) { throw 'Knowledge service did not become ready.' }
    & $taskPython @taskProvision
    if ($LASTEXITCODE -ne 0) { throw 'Independent native maintenance Agent provisioning failed.' }
    Write-Output "Knowledge workbench ready: http://127.0.0.1:$taskPort . Official sources remain empty until configured."
} finally { Pop-Location }

param([switch]$FromRecovery)
$ErrorActionPreference = 'Stop'
$projectPath = Split-Path -Parent $PSScriptRoot
$pythonPath = Join-Path $projectPath '.venv\Scripts\python.exe'
$runtimePath = Join-Path $projectPath '.runtime\knowledge-update'
if (-not (Test-Path -LiteralPath (Join-Path $runtimePath 'phase.json'))) {
    throw 'Run scripts\seed_knowledge_update.py first.'
}
if (Get-NetTCPConnection -LocalPort 8772 -State Listen -ErrorAction SilentlyContinue) {
    throw 'Port 8772 is already in use. Inspect the existing service before starting another.'
}
if ((Test-Path -LiteralPath (Join-Path $runtimePath 'knowledge-mcp-token.txt')) -and (Get-NetTCPConnection -LocalPort 8773 -State Listen -ErrorAction SilentlyContinue)) {
    throw 'Port 8773 is already in use. Inspect the existing MCP before starting another.'
}
$pausePath = Join-Path $runtimePath 'service-paused.json'
if ($FromRecovery -and (Test-Path -LiteralPath $pausePath)) { throw 'Automatic recovery is manually paused.' }
if (-not $FromRecovery -and (Test-Path -LiteralPath $pausePath)) { Remove-Item -LiteralPath $pausePath }
$argumentList = @('-m', 'gov_mcp.knowledge_service', '--runtime', ('"' + $runtimePath + '"'))
$process = Start-Process -FilePath $pythonPath -ArgumentList $argumentList -WorkingDirectory $projectPath -WindowStyle Hidden -PassThru -RedirectStandardOutput (Join-Path $runtimePath 'supervisor.stdout.log') -RedirectStandardError (Join-Path $runtimePath 'supervisor.stderr.log')
@{ supervisor_pid = $process.Id; started_at = (Get-Date).ToUniversalTime().ToString('o') } | ConvertTo-Json | Set-Content -LiteralPath (Join-Path $runtimePath 'launcher.json') -Encoding utf8
$deadline = [DateTime]::UtcNow.AddSeconds(45)
$ready = $false
$lastReadinessError = 'Services have not responded yet.'
$mcpRequired = Test-Path -LiteralPath (Join-Path $runtimePath 'knowledge-mcp-token.txt')
do {
    try {
        $response = Invoke-RestMethod -Uri 'http://127.0.0.1:8772/api/status' -TimeoutSec 2
        if ($response.mode -ne 'knowledge_update') { throw 'Unexpected web service mode.' }
        foreach ($identity in @('knowledge-worker', 'knowledge-maintenance')) {
            $worker = @($response.workers | Where-Object id -EQ $identity)
            if (-not $worker.Count -or $worker[0].stale) { throw ('Waiting for heartbeat: ' + $identity) }
        }
        if ($mcpRequired) {
            $mcpHealth = Invoke-RestMethod -Uri 'http://127.0.0.1:8773/health' -TimeoutSec 2
            if ($mcpHealth.status -ne 'UP' -or -not $mcpHealth.read_only) { throw 'Waiting for read-only MCP.' }
        }
        $ready = $true
    } catch { $lastReadinessError = $_.Exception.Message }
    if (-not $ready -and [DateTime]::UtcNow -lt $deadline) { Start-Sleep -Seconds 1 }
} while (-not $ready -and [DateTime]::UtcNow -lt $deadline)
if (-not $ready) {
    throw ('Readiness was not confirmed within 45 seconds. The launched process may still be running; inspect it and supervisor logs before starting another. Launcher PID: ' + $process.Id + '. Last check: ' + $lastReadinessError)
}
[pscustomobject]@{ LauncherPid=$process.Id; Url='http://127.0.0.1:8772'; Mode=$response.mode; PublishedScopes=$response.counts.heads; ReadinessConfirmed=$true }

param([switch]$ForRestart)
$ErrorActionPreference = 'Stop'
$projectPath = Split-Path -Parent $PSScriptRoot
$runtimePath = [IO.Path]::GetFullPath((Join-Path $projectPath '.runtime\knowledge-update'))
$state = Get-Content -LiteralPath (Join-Path $runtimePath 'service-state.json') -Raw | ConvertFrom-Json
$ownedIds = @($state.supervisor_pid) + @($state.processes.PSObject.Properties | ForEach-Object { $_.Value })
$verified = @()
foreach ($ownedId in $ownedIds) {
    $candidateProcess = Get-CimInstance Win32_Process -Filter "ProcessId=$ownedId" -ErrorAction SilentlyContinue
    if ($candidateProcess) {
        $ownedCommand = $candidateProcess.CommandLine
        if ($ownedCommand -notlike '*gov_mcp.knowledge_*' -or $ownedCommand -notlike ('*' + $runtimePath + '*')) {
            throw "Process $ownedId no longer matches this runtime; refusing to stop it."
        }
        $verified += $candidateProcess
    }
}
if (-not $ForRestart) {
    $pause = @{paused=$true; reason='manual_service_stop'; set_at=[DateTimeOffset]::UtcNow.ToUnixTimeSeconds()}
    [IO.File]::WriteAllText((Join-Path $runtimePath 'service-paused.json'), ($pause | ConvertTo-Json), (New-Object Text.UTF8Encoding($false)))
}
foreach ($candidateProcess in $verified) {
    $fresh = Get-CimInstance Win32_Process -Filter ('ProcessId=' + [int]$candidateProcess.ProcessId) -ErrorAction SilentlyContinue
    if ($fresh -and $fresh.CreationDate -eq $candidateProcess.CreationDate -and $fresh.CommandLine -eq $candidateProcess.CommandLine) { Stop-Process -Id $fresh.ProcessId }
}
Write-Output 'Stopped this runtime supervisor and its owned child processes.'

$ErrorActionPreference = 'Stop'
$projectPath = [IO.Path]::GetFullPath((Split-Path -Parent $PSScriptRoot))
$runtimePath = Join-Path $projectPath '.runtime\knowledge-update'
$registration = Get-Content -LiteralPath (Join-Path $runtimePath 'startup-registration.json') -Raw -Encoding UTF8 | ConvertFrom-Json
$before = Invoke-RestMethod -Uri 'http://127.0.0.1:8772/api/status' -TimeoutSec 10
$checks = [ordered]@{}
$stopped = $false

function Wait-TaskResult([string]$expectedAction, [long]$notBefore) {
    $deadline = [DateTime]::UtcNow.AddSeconds(40)
    do {
        $task = Get-ScheduledTask -TaskName $registration.task_name
        $info = Get-ScheduledTaskInfo -TaskName $registration.task_name
        $state = Get-Content -LiteralPath (Join-Path $runtimePath 'startup-recovery-status.json') -Raw -Encoding UTF8 | ConvertFrom-Json
        if ([string]$task.State -eq 'Ready' -and $info.LastTaskResult -eq 0 -and $state.action -eq $expectedAction -and $state.checked_at -ge $notBefore) { return $true }
        Start-Sleep -Seconds 2
    } while ([DateTime]::UtcNow -lt $deadline)
    return $false
}

try {
    & (Join-Path $PSScriptRoot 'stop_knowledge_update.ps1') | Out-Null
    $stopped = $true
    Start-Sleep -Seconds 2
    $checks.manual_stop_sets_pause = Test-Path -LiteralPath (Join-Path $runtimePath 'service-paused.json')
    $stoppedPorts = @(Get-NetTCPConnection -State Listen -ErrorAction Stop | Where-Object { $_.LocalPort -in @(8772,8773) })
    $checks.owned_services_stopped = $stoppedPorts.Count -eq 0
    $start = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
    Start-ScheduledTask -TaskName $registration.task_name
    $checks.scheduled_check_respects_pause = Wait-TaskResult 'paused' $start
    $afterPausePorts = @(Get-NetTCPConnection -State Listen -ErrorAction Stop | Where-Object { $_.LocalPort -in @(8772,8773) })
    $checks.no_automatic_relaunch_after_manual_stop = $afterPausePorts.Count -eq 0
} finally {
    if ($stopped) {
        & (Join-Path $PSScriptRoot 'start_knowledge_update.ps1') | Out-Null
    }
}
$checks.manual_start_clears_pause = -not (Test-Path -LiteralPath (Join-Path $runtimePath 'service-paused.json'))
$state = Get-Content -LiteralPath (Join-Path $runtimePath 'service-state.json') -Raw -Encoding UTF8 | ConvertFrom-Json
$start = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
Start-ScheduledTask -TaskName $registration.task_name
$checks.scheduled_check_after_resume_is_healthy = Wait-TaskResult 'healthy' $start
$after = Invoke-RestMethod -Uri 'http://127.0.0.1:8772/api/status' -TimeoutSec 10
$newState = Get-Content -LiteralPath (Join-Path $runtimePath 'service-state.json') -Raw -Encoding UTF8 | ConvertFrom-Json
$checks.healthy_resume_does_not_duplicate_supervisor = $state.supervisor_pid -eq $newState.supervisor_pid
$countsMatch = $true
foreach ($key in @('documents','revisions','chunks','latest_chunks','versions','heads')) {
    if ($before.counts.$key -ne $after.counts.$key) { $countsMatch = $false }
}
$checks.business_counts_unchanged = $countsMatch
$checks.no_official_publication = $after.counts.heads -eq 0
$passed = @($checks.Values | Where-Object { -not $_ }).Count -eq 0
$report = @{captured_at=[DateTime]::UtcNow.ToString('o'); passed=$passed; checks=$checks; counts=$after.counts;
    scope='Actual manual stop/pause, scheduled no-op and manual resume with a healthy scheduled check; the service was restored at the end.'}
[IO.File]::WriteAllText((Join-Path $projectPath 'evidence\knowledge-update\startup-manual-control.json'),($report | ConvertTo-Json -Depth 6),(New-Object Text.UTF8Encoding($false)))
[pscustomobject]@{Passed=$passed; CheckCount=$checks.Count; ServicesRunning=$checks.scheduled_check_after_resume_is_healthy}
if (-not $passed) { throw '手动控制检查未全部通过。' }

