function Wait-WinRT($Operation, [Type]$ResultType) {
    if ($ResultType) { $task = $genericTask.MakeGenericMethod($ResultType).Invoke($null, @($Operation)) }
    else { $task = $actionTask.Invoke($null, @($Operation)) }
    if (-not $task.Wait(15000)) { throw 'Native OCR operation timed out' }
    if ($ResultType) { return $task.GetAwaiter().GetResult() }
}
$resolvedInput = [IO.Path]::GetFullPath($InputPath)
if (-not [IO.File]::Exists($resolvedInput) -or ([IO.FileInfo]$resolvedInput).Length -gt 5242880) { throw 'Bounded local PDF required' }
$inputStream = [IO.File]::OpenRead($resolvedInput)
$hasher = [Security.Cryptography.SHA256]::Create()
try { $inputHash = [BitConverter]::ToString($hasher.ComputeHash($inputStream)).Replace('-', '').ToLowerInvariant() }
finally { $hasher.Dispose(); $inputStream.Dispose() }
$engine = $engineType::TryCreateFromLanguage([Activator]::CreateInstance($languageType, @($Language)))
if (-not $engine -or $engine.RecognizerLanguage.LanguageTag -ne $Language) { throw 'Requested native OCR language unavailable' }
$file = Wait-WinRT ($fileType::GetFileFromPathAsync($resolvedInput)) $fileType
$pdf = Wait-WinRT ($pdfType::LoadFromFileAsync($file)) $pdfType
if ($pdf.PageCount -lt 1 -or $pdf.PageCount -gt 20 -or $pdf.IsPasswordProtected) { throw 'Unencrypted PDF of at most 20 pages required for OCR' }
$pages = @()
for ($index = 0; $index -lt $pdf.PageCount; $index++) {
    $page = $pdf.GetPage($index)
    $stream = [Activator]::CreateInstance($streamType)
    $bitmap = $null
    try {
        $width, $height = [double]$page.Size.Width, [double]$page.Size.Height
        if ($width -le 0 -or $height -le 0 -or $width -gt 3000 -or $height -gt 3000) { throw 'PDF page geometry out of bounds' }
        $limit = [Math]::Min(2400, $engineType::MaxImageDimension)
        $scale = $limit / [Math]::Max($width, $height)
        $options = [Activator]::CreateInstance($renderType)
        $options.DestinationWidth = [uint32][Math]::Max(1, [Math]::Round($width * $scale))
        $options.DestinationHeight = [uint32][Math]::Max(1, [Math]::Round($height * $scale))
        Wait-WinRT ($page.RenderToStreamAsync($stream, $options)) $null
        $stream.Seek(0)
        $decoder = Wait-WinRT ($decoderType::CreateAsync($stream)) $decoderType
        if ([double]$decoder.PixelWidth * $decoder.PixelHeight -gt 40000000) { throw 'Rendered PDF image too large' }
        # PDF rendering can be affected by desktop DPI. Enforce pixel bounds at
        # the bitmap decoder too, rather than trusting render-option dimensions.
        $transform = [Activator]::CreateInstance($transformType)
        $ratio = $limit / [Math]::Max($decoder.PixelWidth, $decoder.PixelHeight)
        $transform.ScaledWidth = [uint32][Math]::Max(1, [Math]::Round($decoder.PixelWidth * $ratio))
        $transform.ScaledHeight = [uint32][Math]::Max(1, [Math]::Round($decoder.PixelHeight * $ratio))
        $bitmap = Wait-WinRT ($decoder.GetSoftwareBitmapAsync($pixelFormat::Bgra8, $alphaMode::Ignore,
            $transform, $orientationMode::IgnoreExifOrientation, $colorMode::DoNotColorManage)) $bitmapType
        $result = Wait-WinRT ($engine.RecognizeAsync($bitmap)) $resultType
        $lines = @($result.Lines)
        $text = ($lines | ForEach-Object { $_.Text }) -join "`n"
        if ($text.Length -lt 8 -or $text.Length -gt 16000 -or $lines.Count -gt 800) { throw 'Empty or oversized OCR page' }
        $pages += @{ page=$index+1; text=$text; line_count=$lines.Count; width=$bitmap.PixelWidth; height=$bitmap.PixelHeight }
    } finally {
        if ($bitmap) { $bitmap.Dispose() }
        $stream.Dispose()
        $page.Dispose()
    }
}
@{ schema=1; engine='windows.media.ocr'; language=$engine.RecognizerLanguage.LanguageTag; input_sha256=$inputHash;
   confidence_available=$false; requires_visual_review=$true; pages=$pages } | ConvertTo-Json -Depth 5 -Compress

param([Parameter(Mandatory=$true)][string]$RuntimePath)
$ErrorActionPreference = 'Stop'
[Console]::OutputEncoding = New-Object Text.UTF8Encoding($false)
try {
    $resolvedRuntime = [IO.Path]::GetFullPath($RuntimePath)
    $projectPath = Split-Path -Parent (Split-Path -Parent $resolvedRuntime)
    $marker = Get-Content -LiteralPath (Join-Path $resolvedRuntime 'phase.json') -Raw -Encoding UTF8 | ConvertFrom-Json
    if ($marker.phase -ne 'knowledge_update' -or $marker.schema_version -ne 1) { throw 'Invalid runtime marker' }
    $registration = Get-Content -LiteralPath (Join-Path $resolvedRuntime 'startup-registration.json') -Raw -Encoding UTF8 | ConvertFrom-Json
    $sha = [Security.Cryptography.SHA256]::Create()
    try { $key = ([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($resolvedRuntime)))).Replace('-', '').Substring(0, 16) }
    finally { $sha.Dispose() }
    $expectedName = 'HuaweiICT-KnowledgeUpdate-' + $key
    if ($registration.task_name -ne $expectedName) { throw 'Registration ownership mismatch' }
    try { $task = Get-ScheduledTask -TaskName $expectedName -ErrorAction Stop }
    catch {
        if ($_.FullyQualifiedErrorId -like 'CmdletizationQuery_NotFound_TaskName,*') {
            @{status='missing'; task_name=$expectedName} | ConvertTo-Json -Compress
            exit 0
        }
        throw
    }
    $info = Get-ScheduledTaskInfo -TaskName $expectedName -ErrorAction Stop
    $identity = [Security.Principal.WindowsIdentity]::GetCurrent()
    $taskSid = if ($task.Principal.UserId.StartsWith('S-1-')) { $task.Principal.UserId } else {
        (New-Object Security.Principal.NTAccount($task.Principal.UserId)).Translate([Security.Principal.SecurityIdentifier]).Value
    }
    $expectedShell = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
    $expectedArguments = '-NoLogo -NoProfile -NonInteractive -WindowStyle Hidden -ExecutionPolicy Bypass -File "' + (Join-Path $projectPath 'scripts\ensure_knowledge_update.ps1') + '"'
    $owned = @($task.Actions).Count -eq 1 -and $task.Actions[0].Execute -eq $expectedShell -and $task.Actions[0].Arguments -eq $expectedArguments -and
        $task.Actions[0].WorkingDirectory -eq $projectPath -and $taskSid -eq $identity.User.Value -and [string]$task.Principal.RunLevel -eq 'Limited' -and [string]$task.Principal.LogonType -eq 'Interactive'
    $login = @($task.Triggers | Where-Object { $_.CimClass.CimClassName -eq 'MSFT_TaskLogonTrigger' -and $_.Enabled })
    $periodic = @($task.Triggers | Where-Object { $_.CimClass.CimClassName -eq 'MSFT_TaskTimeTrigger' -and $_.Enabled -and $_.Repetition.Interval -eq 'PT5M' -and -not $_.EndBoundary -and -not $_.Repetition.Duration })
    $loginUserMatches = $false
    if ($login.Count -eq 1 -and $login[0].UserId) {
        $loginSid = if ($login[0].UserId.StartsWith('S-1-')) { $login[0].UserId } else {
            (New-Object Security.Principal.NTAccount($login[0].UserId)).Translate([Security.Principal.SecurityIdentifier]).Value
        }
        $loginUserMatches = $loginSid -eq $identity.User.Value
    }
    [ordered]@{ status='observed'; task_name=$expectedName; enabled=[bool]$task.Settings.Enabled; task_state=[string]$task.State;
        ownership_verified=[bool]$owned; configuration_matches=(@($task.Triggers).Count -eq 2 -and $loginUserMatches -and $periodic.Count -eq 1);
        last_run=$info.LastRunTime.ToUniversalTime().ToString('o'); next_run=$info.NextRunTime.ToUniversalTime().ToString('o');
        last_result=$info.LastTaskResult; missed_runs=$info.NumberOfMissedRuns } | ConvertTo-Json -Compress
} catch {
    @{status='unavailable'; error_kind=$_.Exception.GetType().Name} | ConvertTo-Json -Compress
}
